{"command":"cat > /workspace/src/common.cpp <<'EOF'
#include "common.h"
#include <unistd.h>
#include <sys/stat.h>

const char* BT_VERSION = "9560abc";
Output OUT;

void Output::flush() {
    if (!buf.empty()) {
        fwrite(buf.data(), 1, buf.size(), stdout);
        buf.clear();
    }
    fflush(stdout);
}

void outi(pos_t v) {
    char tmp[32];
    int n = snprintf(tmp, sizeof(tmp), "%lld", v);
    OUT.buf.append(tmp, n);
}

void errmsg(const string& msg) {
    fwrite(msg.data(), 1, msg.size(), stderr);
}

[[noreturn]] void die(const string& msg) {
    if (!OUT.newApi) OUT.flush();
    errmsg(msg);
    fflush(stderr);
    _exit(1);
}

[[noreturn]] void dieFlush(const string& msg) {
    OUT.flush();
    errmsg(msg);
    fflush(stderr);
    _exit(1);
}

const std::map<std::string, std::string>& helpTexts();

void printHelp(const string& tool, FILE* to) {
    auto& m = helpTexts();
    auto it = m.find(tool);
    if (it != m.end()) fwrite(it->second.data(), 1, it->second.size(), to);
}

[[noreturn]] void helpAndExit(const string& tool, const string& err, int rc) {
    OUT.flush();
    printHelp(tool, stderr);
    if (!err.empty()) errmsg(err);
    fflush(stderr);
    exit(rc);
}

// ---------------------------------------------------------------- strings
void splitTab(const string& s, vector<string>& out) {
    out.clear();
    size_t st = 0;
    while (true) {
        size_t p = s.find('\t', st);
        if (p == string::npos) { out.emplace_back(s, st); break; }
        out.emplace_back(s, st, p - st);
        st = p + 1;
    }
}

void split(const string& s, char d, vector<string>& out) {
    out.clear();
    size_t st = 0;
    while (true) {
        size_t p = s.find(d, st);
        if (p == string::npos) { out.emplace_back(s, st); break; }
        out.emplace_back(s, st, p - st);
        st = p + 1;
    }
}

vector<string> splitv(const string& s, char d) { vector<string> v; split(s, d, v); return v; }

string join(const vector<string>& v, const string& d) {
    string r;
    for (size_t i = 0; i < v.size(); i++) { if (i) r += d; r += v[i]; }
    return r;
}

bool isUInt(const string& s) {
    if (s.empty()) return false;
    for (char c : s) if (c < '0' || c > '9') return false;
    return true;
}
bool isInt(const string& s) {
    if (s.empty()) return false;
    size_t i = 0;
    if (s[0] == '-' || s[0] == '+') { i = 1; if (s.size() == 1) return false; }
    for (; i < s.size(); i++) if (s[i] < '0' || s[i] > '9') return false;
    return true;
}
bool isNumeric(const string& s) {
    if (s.empty()) return false;
    char* end = nullptr;
    strtod(s.c_str(), &end);
    return end && *end == 0 && end != s.c_str();
}
bool startsWith(const string& s, const string& p) { return s.size() >= p.size() && s.compare(0, p.size(), p) == 0; }
bool endsWith(const string& s, const string& p) { return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0; }

string itos(pos_t v) { char t[32]; snprintf(t, sizeof t, "%lld", v); return t; }
string fmtG(double v, int prec) { char t[512]; snprintf(t, sizeof t, "%.*g", prec, v); return t; }
string fmtDefault(double v) { char t[64]; snprintf(t, sizeof t, "%g", v); return t; }
string fmtFixed(double v, int prec) { char t[512]; snprintf(t, sizeof t, "%.*f", prec, v); return t; }

pos_t toPos(const string& s) {
    if (!isInt(s)) die("***** ERROR: illegal number \"" + s + "\". Exiting...\n");
    return strtoll(s.c_str(), nullptr, 10);
}
double toDouble(const string& s) { return atof(s.c_str()); }
int toIntArg(const string& s) { return atoi(s.c_str()); }

// ---------------------------------------------------------------- input
bool isStdinName(const string& fn) { return fn == "-" || fn == "stdin" || fn == "/dev/stdin"; }
bool fileExists(const string& fn) { struct stat st; return stat(fn.c_str(), &st) == 0; }

bool InFile::open(const string& fn) {
    name = fn;
    int fd;
    if (isStdinName(fn)) fd = dup(0);
    else fd = ::open(fn.c_str(), 0);
    if (fd < 0) return false;
    struct stat st;
    if (fstat(fd, &st) == 0 && S_ISDIR(st.st_mode)) { ::close(fd); return false; }
    gz = gzdopen(fd, "rb");
    if (!gz) { ::close(fd); return false; }
    gzbuffer(gz, 1 << 17);
    gzipped = gzdirect(gz) == 0;
    rcap = 1 << 16;
    rbuf = (char*)malloc(rcap);
    rlen = rpos = 0;
    eof = false;
    return true;
}

void InFile::close() {
    if (gz) { gzclose(gz); gz = nullptr; }
    if (rbuf) { free(rbuf); rbuf = nullptr; }
}

bool InFile::fill() {
    if (eof) return false;
    if (rpos > 0) {
        memmove(rbuf, rbuf + rpos, rlen - rpos);
        rlen -= rpos; rpos = 0;
    }
    if (rlen == rcap) { rcap *= 2; rbuf = (char*)realloc(rbuf, rcap); }
    int n = gzread(gz, rbuf + rlen, (unsigned)(rcap - rlen));
    if (n <= 0) { eof = true; return false; }
    rlen += n;
    return true;
}

bool InFile::getline(string& line) {
    if (!gz) return false;
    while (true) {
        char* s = rbuf + rpos;
        char* nl = (char*)memchr(s, '\n', rlen - rpos);
        if (nl) {
            size_t n = nl - s;
            line.assign(s, n);
            rpos += n + 1;
            if (!line.empty() && line.back() == '\r') line.pop_back();
            return true;
        }
        if (!fill()) {
            if (rpos < rlen) {
                line.assign(rbuf + rpos, rlen - rpos);
                rpos = rlen;
                if (!line.empty() && line.back() == '\r') line.pop_back();
                return true;
            }
            return false;
        }
    }
}

// ---------------------------------------------------------------- genome
bool Genome::load(const string& fn) {
    file = fn;
    InFile in;
    if (!in.open(fn)) die("Error: The requested genome file (" + fn + ") could not be opened. Exiting!\n");
    string line;
    vector<string> f;
    long ln = 0;
    while (in.getline(line)) {
        ln++;
        if (line.empty()) continue;
        if (line[0] == '#') continue;
        splitTab(line, f);
        if (f.size() < 2) {
            die("Less than the req'd two fields were encountered in the genome file (" + fn + ") at line " + itos(ln) + ".  Exiting.\n");
        }
        const char* p = f[1].c_str();
        while (*p == ' ') p++;
        if (!((*p >= '0' && *p <= '9') || ((*p == '-' || *p == '+') && p[1] >= '0' && p[1] <= '9'))) continue;
        pos_t sz = strtoll(p, nullptr, 10);
        if (!sizes.count(f[0])) {
            order[f[0]] = (int)names.size();
            names.push_back(f[0]);
        }
        sizes[f[0]] = sz;
    }
    return true;
}
EOF"}

