#include "record.h"
#include "bam.h"

string Rec::name() const {
    if (ft == FT_BED) return f.size() > 3 ? f[3] : string();
    if (ft == FT_GFF) return f.size() > 2 ? f[2] : string();
    if (ft == FT_VCF) return f.size() > 2 ? f[2] : string();
    if (ft == FT_BAM) return f.size() > 3 ? f[3] : string();
    return string();
}
string Rec::score() const {
    if (ft == FT_BED || ft == FT_BAM) return f.size() > 4 ? f[4] : string();
    if (ft == FT_GFF) return f.size() > 5 ? f[5] : string();
    if (ft == FT_VCF) return f.size() > 5 ? f[5] : string();
    return string();
}

bool isHeaderLine(const string& line) {
    if (line.empty()) return false;
    if (line[0] == '#') return true;
    if (startsWith(line, "track")) return true;
    if (startsWith(line, "browser")) return true;
    return false;
}

static void appendFieldsGff(string& o, const vector<string>& f, const string* s3, const string* s4) {
    for (size_t i = 0; i < f.size(); i++) {
        if (i > 0 && i < 9) o += '\t';
        if (i == 3 && s3) o += *s3;
        else if (i == 4 && s4) o += *s4;
        else o += f[i];
    }
}

void appendRec(string& o, const Rec& r) {
    if (r.ft == FT_GFF) { appendFieldsGff(o, r.f, nullptr, nullptr); return; }
    for (size_t i = 0; i < r.f.size(); i++) {
        if (i) o += '\t';
        o += r.f[i];
    }
}

string recLine(const Rec& r) { string s; appendRec(s, r); return s; }

void appendRecCoords(string& o, const Rec& r, pos_t s, pos_t e) {
    if (r.ft == FT_GFF) {
        string a = itos(s + 1), b = itos(e);
        appendFieldsGff(o, r.f, &a, &b);
        return;
    }
    if (r.ft == FT_VCF) {
        for (size_t i = 0; i < r.f.size(); i++) {
            if (i) o += '\t';
            if (i == 1) o += itos(s + 1);
            else o += r.f[i];
        }
        return;
    }
    for (size_t i = 0; i < r.f.size(); i++) {
        if (i) o += '\t';
        if (i == 1) o += itos(s);
        else if (i == 2) o += itos(e);
        else o += r.f[i];
    }
}

void appendNullRec(string& o, const Rec& proto, int ft, int bk, int nf) {
    (void)proto;
    if (ft == FT_GFF) { o += ".\t.\t.\t-1\t-1\t.\t.\t.\t."; return; }
    if (ft == FT_VCF) { o += ".\t-1\t.\t.\t.\t.\t.\t."; return; }
    o += ".\t-1\t-1";
    if (bk == BK_BED3) return;
    if (bk == BK_BED4) { o += "\t."; return; }
    if (bk == BK_BED5) { o += "\t.\t-1"; return; }
    if (bk == BK_BED6) { o += "\t.\t-1\t."; return; }
    if (bk == BK_BED12) { o += "\t.\t-1\t.\t.\t.\t.\t.\t.\t."; return; }
    for (int i = 3; i < nf; i++) o += "\t.";
}

void getBlocks(const Rec& r, vector<std::pair<pos_t, pos_t>>& blocks, bool splitD) {
    blocks.clear();
    if (r.ft == FT_BAM && r.bam) {
        bamGetBlocks(r, blocks, splitD);
        return;
    }
    if (r.ft == FT_BED && r.f.size() >= 12 && (r.bk == BK_BED12 || r.f.size() >= 12)) {
        int n = atoi(r.f[9].c_str());
        vector<string> sz, st;
        split(r.f[10], ',', sz);
        split(r.f[11], ',', st);
        if (n > 0 && (int)sz.size() >= n && (int)st.size() >= n) {
            for (int i = 0; i < n; i++) {
                pos_t bs = r.ostart + atoll(st[i].c_str());
                pos_t be = bs + atoll(sz[i].c_str());
                blocks.push_back({bs, be});
            }
            return;
        }
    }
    blocks.push_back({r.start, r.end});
}

// ------------------------------------------------------------------ reader

bool RecReader::getRawLine(string& line) {
    if (pendPos < pending.size()) { line = std::move(pending[pendPos++]); if (pendPos == pending.size()) { pending.clear(); pendPos = 0; } return true; }
    return in.getline(line);
}

static string typeErr(const string& fn) {
    return "Error: unable to open file or unable to determine types for file " + fn + "\n\n"
           "- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n"
           "- Also ensure that your file has integer chromosome coordinates in the \n"
           "  expected columns (e.g., cols 2 and 3 for BED).\n";
}

bool RecReader::open(const string& fname, bool dieOnFail) {
    fn = fname;
    if (!in.open(fn)) {
        if (!dieOnFail) return false;
        die("Error: Unable to open file " + fn + ". Exiting.\n");
    }
    // BAM detection
    if (in.gzipped) {
        // peek
        string first;
        if (bamDetect(in)) {
            isBam = true;
            ft = FT_BAM;
            bamOpenReader(*this, in);
            return true;
        }
    }
    // read until the first data line
    string line;
    bool vcfHeader = false;
    bool gotData = false;
    while (in.getline(line)) {
        if (line.empty()) { continue; }
        if (isHeaderLine(line)) {
            if (startsWith(line, "##fileformat=VCF")) vcfHeader = true;
            header.push_back(line);
            continue;
        }
        pending.push_back(line);
        gotData = true;
        break;
    }
    if (!gotData) { empty = true; ft = FT_BED; bk = BK_BED3; nf = 3; return true; }
    // buffer additional lines for consistency checking (up to ~64KB)
    size_t bytes = pending[0].size();
    while (bytes < 65536) {
        if (!in.getline(line)) break;
        bytes += line.size() + 1;
        pending.push_back(line);
    }
    splitTab(pending[0], tmp);
    nf = (int)tmp.size();
    if (vcfHeader) {
        if (nf < 8 || !isInt(tmp[1])) die(typeErr(fn));
        ft = FT_VCF;
    } else if (nf >= 3 && isInt(tmp[1]) && isInt(tmp[2])) {
        ft = FT_BED;
        if (nf == 3) bk = BK_BED3;
        else if (nf == 4) bk = BK_BED4;
        else if (nf == 5) bk = isNumeric(tmp[4]) ? BK_BED5 : BK_PLUS;
        else if (nf == 6) bk = (tmp[5] == "+" || tmp[5] == "-" || tmp[5] == ".") ? BK_BED6 : BK_PLUS;
        else if (nf == 12) bk = BK_BED12;
        else bk = BK_PLUS;
        if (strtoll(tmp[1].c_str(), 0, 10) > strtoll(tmp[2].c_str(), 0, 10)) die(typeErr(fn));
    } else if (nf >= 8 && isInt(tmp[3]) && isInt(tmp[4])) {
        ft = FT_GFF;
    } else {
        die(typeErr(fn));
    }
    if (!noTypeCheckErr && ft == FT_BED) {
        for (size_t i = 1; i < pending.size(); i++) {
            const string& l = pending[i];
            if (l.empty() || isHeaderLine(l)) continue;
            int c = 1;
            for (char ch : l) if (ch == '\t') c++;
            if (c != nf) {
                die("Error: Type checker found wrong number of fields while tokenizing data line.\n"
                    "Perhaps you have extra TAB at the end of your line? Check with \"cat -t\"\n");
            }
        }
    }
    return true;
}

static pos_t vcfInfoInt(const string& info, const char* key, bool& found) {
    found = false;
    size_t kl = strlen(key);
    size_t p = 0;
    while (p < info.size()) {
        size_t q = info.find(';', p);
        if (q == string::npos) q = info.size();
        if (q - p > kl && info.compare(p, kl, key) == 0 && info[p + kl] == '=') {
            found = true;
            return strtoll(info.c_str() + p + kl + 1, nullptr, 10);
        }
        p = q + 1;
    }
    return 0;
}

bool RecReader::parseLine(const string& line, Rec& r) {
    splitTab(line, r.f);
    r.ft = ft;
    r.bk = bk;
    if (ft == FT_BED) {
        if (r.f.size() < 3) die("Error: Invalid record in file " + fn + ". Record is \n" + line + "\n");
        r.start = toPos(r.f[1]);
        r.end = toPos(r.f[2]);
        if (r.f.size() >= 6) {
            const string& s = r.f[5];
            r.strand = (s == "+") ? '+' : (s == "-") ? '-' : '.';
            r.hasStrand = true;
        } else { r.strand = '.'; r.hasStrand = false; }
    } else if (ft == FT_GFF) {
        if (r.f.size() < 8) die("Error: Invalid record in file " + fn + ". Record is \n" + line + "\n");
        r.start = toPos(r.f[3]) - 1;
        r.end = toPos(r.f[4]);
        const string& s = r.f[6];
        r.strand = (s == "+") ? '+' : (s == "-") ? '-' : '.';
        r.hasStrand = true;
    } else if (ft == FT_VCF) {
        if (r.f.size() < 8) die("Error: Invalid record in file " + fn + ". Record is \n" + line + "\n");
        r.start = toPos(r.f[1]) - 1;
        const string& ref = r.f[3];
        const string& alt = r.f[4];
        pos_t len = (pos_t)ref.size();
        if (!alt.empty() && alt[0] == '<') {
            bool fEnd, fLen;
            pos_t endv = vcfInfoInt(r.f[7], "END", fEnd);
            pos_t svlen = vcfInfoInt(r.f[7], "SVLEN", fLen);
            if (alt.find("INS") != string::npos) len = 0;
            else if (fEnd) len = endv - r.start;
            else if (fLen) len = svlen < 0 ? -svlen : svlen;
        }
        r.end = r.start + len;
        r.strand = '.';
        r.hasStrand = false;
    }
    r.ostart = r.start;
    r.oend = r.end;
    if (r.start < 0 || r.end < r.start) die("Error: Invalid record in file " + fn + ". Record is \n" + line + "\n");
    r.zl = false;
    if (r.start == r.end) {
        r.zl = true;
        r.start -= 1;
        r.end += 1;
    }
    return true;
}

bool RecReader::next(Rec& r) {
    if (isBam) return bamNextRec(*this, r);
    string line;
    blankSeen = false;
    while (getRawLine(line)) {
        lineNo++;
        if (line.empty()) { blankSeen = true; continue; }
        if (isHeaderLine(line)) continue;
        parseLine(line, r);
        r.idx = recNo++;
        return true;
    }
    return false;
}

void readAll(const string& fn, vector<Rec>& recs, RecReader* rdOut) {
    RecReader rd;
    RecReader& R = rdOut ? *rdOut : rd;
    R.open(fn);
    Rec r;
    while (R.next(r)) recs.push_back(r);
}
EOF"}

