#include "overlap.h"

static inline int binLevel(pos_t s, pos_t e, pos_t& bin) {
    pos_t ee = e - 1;
    if (ee < s) ee = s;
    for (int L = 0; L < 8; L++) {
        int sh = 14 + 3 * L;
        if ((s >> sh) == (ee >> sh)) { bin = s >> sh; return L; }
    }
    bin = 0;
    return 7;
}

void BinIndex::build(const vector<Rec>& r) {
    recs = &r;
    for (int i = 0; i < (int)r.size(); i++) add(i);
}

void BinIndex::add(int i) {
    const Rec& r = (*recs)[i];
    pos_t bin;
    int L = binLevel(r.start, r.end, bin);
    chroms[r.chrom()].lv[L][bin].push_back(i);
}

void BinIndex::query(const string& chrom, pos_t s, pos_t e, vector<int>& out) const {
    out.clear();
    auto it = chroms.find(chrom);
    if (it == chroms.end()) return;
    const ChromBins& cb = it->second;
    pos_t ee = e - 1;
    if (ee < s) ee = s;
    for (int L = 0; L < 8; L++) {
        const auto& m = cb.lv[L];
        if (m.empty()) continue;
        int sh = 14 + 3 * L;
        pos_t b0 = s >> sh, b1 = ee >> sh;
        if ((pos_t)m.size() < b1 - b0 + 1) {
            // iterate map keys instead (collect sorted)
            vector<pos_t> keys;
            for (auto& kv : m) if (kv.first >= b0 && kv.first <= b1) keys.push_back(kv.first);
            std::sort(keys.begin(), keys.end());
            for (pos_t k : keys) {
                for (int idx : m.at(k)) {
                    const Rec& r = (*recs)[idx];
                    if (r.start < e && r.end > s) out.push_back(idx);
                }
            }
        } else {
            for (pos_t b = b0; b <= b1; b++) {
                auto jt = m.find(b);
                if (jt == m.end()) continue;
                for (int idx : jt->second) {
                    const Rec& r = (*recs)[idx];
                    if (r.start < e && r.end > s) out.push_back(idx);
                }
            }
        }
    }
}

bool strandOk(const Rec& a, const Rec& b, const OvlOpts& o) {
    if (o.sameStrand) {
        if (a.strand == '.' || b.strand == '.') return false;
        return a.strand == b.strand;
    }
    if (o.diffStrand) {
        if (a.strand == '.' || b.strand == '.') return false;
        return a.strand != b.strand;
    }
    return true;
}

bool fracOk(pos_t ovl, pos_t lenA, pos_t lenB, const OvlOpts& o) {
    if (ovl <= 0) return false;
    double fa = (double)ovl / (double)lenA;
    double fb = (double)ovl / (double)lenB;
    double F = o.FSet ? o.F : (o.recip ? o.f : o.F);
    if (o.either) {
        return fa >= o.f || fb >= F;
    }
    if (o.recip) {
        return fa >= o.f && fb >= F;
    }
    return fa >= o.f && fb >= o.F;
}

pos_t splitOverlap(const Rec& a, const Rec& b) {
    vector<std::pair<pos_t, pos_t>> ba, bb;
    getBlocks(a, ba);
    getBlocks(b, bb);
    pos_t tot = 0;
    for (auto& x : ba) for (auto& y : bb) {
        pos_t o = ovlLen(x.first, x.second, y.first, y.second);
        if (o > 0) tot += o;
    }
    return tot;
}

bool hitOk(const Rec& a, const Rec& b, const OvlOpts& o) {
    if (!strandOk(a, b, o)) return false;
    if (o.split) {
        vector<std::pair<pos_t, pos_t>> ba, bb;
        getBlocks(a, ba);
        getBlocks(b, bb);
        pos_t tot = 0, la = 0, lb = 0;
        for (auto& x : ba) la += x.second - x.first;
        for (auto& y : bb) lb += y.second - y.first;
        for (auto& x : ba) for (auto& y : bb) {
            pos_t ov = ovlLen(x.first, x.second, y.first, y.second);
            if (ov > 0) tot += ov;
        }
        return fracOk(tot, la, lb, o);
    }
    pos_t ov = ovlLen(a.start, a.end, b.start, b.end);
    return fracOk(ov, a.end - a.start, b.end - b.start, o);
}

bool parseOvlOpt(const vector<string>& a, size_t& i, OvlOpts& o, const string& tool) {
    (void)tool;
    const string& s = a[i];
    if (s == "-s") { o.sameStrand = true; return true; }
    if (s == "-S") { o.diffStrand = true; return true; }
    if (s == "-r") { o.recip = true; return true; }
    if (s == "-e") { o.either = true; return true; }
    if (s == "-split") { o.split = true; return true; }
    if (s == "-f") { if (i + 1 < a.size()) { o.f = atof(a[++i].c_str()); o.fSet = true; } return true; }
    if (s == "-F") { if (i + 1 < a.size()) { o.F = atof(a[++i].c_str()); o.FSet = true; } return true; }
    return false;
}
