// compute printable intersection region and overlap per bedtools quirks
static void regionOf(const Rec& a, const Rec& b, pos_t& s, pos_t& e) {
    pos_t as = a.zl ? a.ostart : a.start, ae = a.zl ? a.oend : a.end;
    s = std::max(as, b.start);
    e = std::min(ae, b.end);
}
static pos_t overlapOut(const Rec& a, const Rec& b) {
    pos_t s, e;
    regionOf(a, b, s, e);
    pos_t ov = e - s;
    if (b.zl) ov -= 2;
    return ov;
}

int main_intersect(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fa;
    vector<string> fbs;
    vector<string> names;
    bool useNames = false, useFilenames = false, sortout = false;
    bool wa = false, wb = false, loj = false, wo = false, wao = false, u = false, c = false, C = false, v = false;
    bool header = false, sorted = false, bedOut = false;
    bool haveA = false, haveB = false;
