        if (s == "-h" || s == "--help") helpAndExit("intersect");
        if (s == "-a") {
            if (i + 1 >= a.size()) helpAndExit("intersect", "***** ERROR: -a option given, but no query file specified. *****\n");
            fa = a[++i]; haveA = true;
