#include "ops.h"

static const char* OPS[] = {"sum", "min", "max", "absmin", "absmax", "mean", "median", "mode", "antimode",
                            "stdev", "sstdev", "collapse", "distinct", "distinct_sort_num",
                            "distinct_sort_num_desc", "distinct_only", "count", "count_distinct", "first",
                            "last", "concat", "freqdesc", "freqasc", nullptr};

bool isValidOp(const string& op) {
    for (int i = 0; OPS[i]; i++) if (op == OPS[i]) return true;
    return false;
}

bool btIsNumeric(const string& s) {
    if (s.empty()) return false;
    for (char c : s) {
        if (!((c >= '0' && c <= '9') || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E')) return false;
    }
    char* end;
    strtod(s.c_str(), &end);
    return end != s.c_str();
}

static double numVal(const string& s, int col, OpState& st) {
    if (!btIsNumeric(s)) {
        st.nonNum = true;
        st.errMsg = " ***** WARNING: Non numeric value " + s + " in " + itos(col) + ".";
        return NAN;
    }
    return atof(s.c_str());
}

static string fmtNum(double v, int prec) {
    if (std::isnan(v)) return ".";
    return fmtG(v, prec);
}

string computeOp(const string& op, const vector<const string*>& vals, int col, int prec,
                 const string& delim, OpState& st) {
    size_t n = vals.size();
    if (op == "count") return itos((pos_t)n);
    if (op == "count_distinct") {
        std::set<string> s;
        for (auto* v : vals) s.insert(*v);
        return itos((pos_t)s.size());
    }
    if (n == 0) return ".";
    if (op == "sum" || op == "mean" || op == "min" || op == "max" || op == "absmin" || op == "absmax" ||
        op == "stdev" || op == "sstdev" || op == "median") {
        vector<double> x;
        x.reserve(n);
        bool bad = false;
        for (auto* v : vals) { double d = numVal(*v, col, st); if (std::isnan(d)) bad = true; x.push_back(d); }
        if (bad) return ".";
        if (op == "sum") { double s = 0; for (double d : x) s += d; return fmtNum(s, prec); }
        if (op == "mean") { double s = 0; for (double d : x) s += d; return fmtNum(s / n, prec); }
        if (op == "min") { double m = x[0]; for (double d : x) if (d < m) m = d; return fmtNum(m, prec); }
        if (op == "max") { double m = x[0]; for (double d : x) if (d > m) m = d; return fmtNum(m, prec); }
        if (op == "absmin") { double m = fabs(x[0]); for (double d : x) if (fabs(d) < m) m = fabs(d); return fmtNum(m, prec); }
        if (op == "absmax") { double m = fabs(x[0]); for (double d : x) if (fabs(d) > m) m = fabs(d); return fmtNum(m, prec); }
        if (op == "median") {
            std::sort(x.begin(), x.end());
            double m;
            if (n % 2 == 1) m = x[n / 2];
            else m = (x[n / 2 - 1] + x[n / 2]) / 2.0;
            return fmtNum(m, prec);
        }
        if (op == "stdev" || op == "sstdev") {
            double s = 0; for (double d : x) s += d;
            double mean = s / n;
            double t = 0; for (double d : x) t += (d - mean) * (d - mean);
            double var;
            if (op == "stdev") var = t / n;
            else { if (n < 2) return "."; var = t / (n - 1); }
            return fmtNum(sqrt(var), prec);
        }
    }
    if (op == "collapse" || op == "concat") {
        string r;
        const string& d = (op == "concat") ? string() : delim;
        for (size_t i = 0; i < n; i++) { if (i) r += d; r += *vals[i]; }
        return r;
    }
    if (op == "first") return *vals[0];
    if (op == "last") return *vals[n - 1];
    if (op == "distinct") {
        std::set<string> s;
        for (auto* v : vals) s.insert(*v);
        string r; bool first = true;
        for (auto& v : s) { if (!first) r += delim; r += v; first = false; }
        return r;
    }
    if (op == "distinct_only") {
        std::map<string, int> m;
        for (auto* v : vals) m[*v]++;
        string r; bool first = true;
        for (auto& kv : m) {
            if (kv.second == 1) { if (!first) r += delim; r += kv.first; }
            first = false;
        }
        return r;
    }
    if (op == "distinct_sort_num" || op == "distinct_sort_num_desc") {
        vector<double> x;
        for (auto* v : vals) x.push_back(numVal(*v, col, st));
        std::sort(x.begin(), x.end());
        x.erase(std::unique(x.begin(), x.end()), x.end());
        if (op == "distinct_sort_num_desc") std::reverse(x.begin(), x.end());
        string r;
        for (size_t i = 0; i < x.size(); i++) { if (i) r += delim; r += fmtDefault(x[i]); }
        return r;
    }
    if (op == "mode" || op == "antimode") {
        std::map<string, int> m;
        for (auto* v : vals) m[*v]++;
        const string* best = nullptr; int bc = 0;
        for (auto& kv : m) {
            if (!best) { best = &kv.first; bc = kv.second; continue; }
            if (op == "mode" ? kv.second > bc : kv.second < bc) { best = &kv.first; bc = kv.second; }
        }
        return *best;
    }
    if (op == "freqdesc" || op == "freqasc") {
        std::map<string, int> m;
        for (auto* v : vals) m[*v]++;
        vector<std::pair<string, int>> x(m.begin(), m.end());
        if (op == "freqdesc")
            std::stable_sort(x.begin(), x.end(), [](const std::pair<string, int>& a, const std::pair<string, int>& b) { return a.second > b.second; });
        else
            std::stable_sort(x.begin(), x.end(), [](const std::pair<string, int>& a, const std::pair<string, int>& b) { return a.second < b.second; });
        string r;
        for (size_t i = 0; i < x.size(); i++) { if (i) r += delim; r += x[i].first + ":" + itos(x[i].second); }
        return r;
    }
    return ".";
}
EOF"}

