[[noreturn]] static void opErr(const string& msg) {
    OUT.flush();
    errmsg("\n*****\n***** ERROR: " + msg + "\n");
    fflush(stderr);
    _exit(0);
}

void validateOps(OpList& L, int nf, const string& fn, bool requireBoth) {
    (void)requireBoth;
    if (!L.haveC || !L.haveO) opErr("There must be at least one column and at least one operation named.");
    vector<string> cs = splitv(L.colStr, ','), os = splitv(L.opStr, ',');
    L.cols.clear(); L.ops.clear();
