    for (auto& o : os) L.ops.push_back(o);
    if (L.cols.size() > 1 && L.ops.size() > 1 && L.cols.size() != L.ops.size()) {
        opErr("There are " + itos(L.cols.size()) + " columns given, but there are " + itos(L.ops.size()) +
              " operations.\n\tPlease provide either a single operation that will be applied to all listed columns, \n"
              "\ta single column to which all operations will be applied,\n\tor an operation for each column.");
    }
    for (auto& o : L.ops) if (!isValidOp(o)) opErr(o + " is not a valid operation. ");
    if (L.cols.size() == 1 && L.ops.size() > 1) L.cols.assign(L.ops.size(), L.cols[0]);
    if (L.ops.size() == 1 && L.cols.size() > 1) L.ops.assign(L.cols.size(), L.ops[0]);
    for (int c : L.cols) {
        if (c < 1 || c > nf) opErr("Requested column " + itos(c) + ", but database file " + fn + " only has fields 1 - " + itos(nf) + ".");
    }
}

string computeOps(const OpList& L, const vector<const Rec*>& recs) {
    string out;
    OpState st;
    vector<const string*> vals;
    for (size_t i = 0; i < L.ops.size(); i++) {
        int c = L.cols[i];
        vals.clear();
        for (auto* r : recs) {
            if (c - 1 < (int)r->f.size()) vals.push_back(&r->f[c - 1]);
        }
        if (i) out += '\t';
        out += computeOp(L.ops[i], vals, c, L.prec, L.delim, st);
    }
    if (st.nonNum) { errmsg(st.errMsg + "\n"); }
    return out;
}
