        ob += computeOps(L, rp);
    }
    outnl();
}

int main_merge(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn;
    bool haveI = false;
    bool strandSpecific = false;
    char onlyStrand = 0;
    pos_t dist = 0;
    bool header = false;
    OpList L;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("merge");
        if (s == "-i") {
            if (i + 1 >= a.size()) helpAndExit("merge", "***** ERROR: -i option given, but no input file specified. *****\n");
            fn = a[++i]; haveI = true;
        } else if (s == "-s") strandSpecific = true;
        else if (s == "-S") {
            if (i + 1 >= a.size() || (a[i + 1] != "+" && a[i + 1] != "-"))
                helpAndExit("merge", "***** ERROR: -S option must be followed by + or -. *****\n");
            onlyStrand = a[++i][0];
        } else if (s == "-d") {
            if (i + 1 < a.size()) dist = toPos(a[++i]);
        } else if (s == "-c") { if (i + 1 < a.size()) { L.colStr = a[++i]; L.haveC = true; } }
        else if (s == "-o") { if (i + 1 < a.size()) { L.opStr = a[++i]; L.haveO = true; } }
        else if (s == "-delim") { if (i + 1 < a.size()) L.delim = a[++i]; }
        else if (s == "-prec") { if (i + 1 < a.size()) L.prec = atoi(a[++i].c_str()); }
        else if (s == "-header") header = true;
        else if (s == "-bed" || s == "-nobuf" || s == "-n" || s == "-nms" || s == "-scores") {}
        else if (s == "-iobuf") { if (i + 1 < a.size()) i++; }
        else helpAndExit("merge", "***** ERROR: Unrecognized parameter: " + s + " *****\n");
    }
    if (!haveI) {
        if (isatty(0)) helpAndExit("merge", "");
        fn = "stdin";
