    rd.open(fn);
    bool haveOps = L.haveC || L.haveO;
    if (haveOps) validateOps(L, rd.nf, fn);
    if (header) for (auto& h : rd.header) { outs(h); outnl(); }

    Rec r;
    std::set<string> seenChroms;
    string prevChrom;
    pos_t prevStart = -1;
    bool havePrev = false;
    auto sortErr = [&](const Rec& x) {
