                if (r.end > c.e) c.e = r.end;
                c.recs.push_back(r);
            } else {
                if (c.open) printCluster(c, L, haveOps);
                c.open = true; c.chrom = r.chrom(); c.s = r.start; c.e = r.end;
                c.recs.clear(); c.recs.push_back(r);
            }
        }
        if (c.open) printCluster(c, L, haveOps);
    } else {
        // clusters per strand; output in creation order per chromosome
        vector<Cluster> done;     // all clusters of current chrom in creation order
        int openIdx[2] = {-1, -1};
        string curChrom;
        auto flushAll = [&]() {
            for (auto& c : done) printCluster(c, L, haveOps);
            done.clear(); openIdx[0] = openIdx[1] = -1;
        };
        while (rd.next(r)) {
            if (rd.blankSeen) { flushAll(); havePrev = false; }
            if (havePrev) {
                if (r.chrom() != prevChrom) {
                    if (seenChroms.count(r.chrom())) sortErr(r);
                } else if (r.start < prevStart) sortErr(r);
            }
            if (!havePrev || r.chrom() != prevChrom) seenChroms.insert(r.chrom());
            prevChrom = r.chrom(); prevStart = r.start; havePrev = true;
            if (r.chrom() != curChrom) { flushAll(); curChrom = r.chrom(); }
            if (r.strand != '+' && r.strand != '-') continue;
            if (onlyStrand && r.strand != onlyStrand) continue;
            int si = r.strand == '+' ? 0 : 1;
            int oi = openIdx[si];
            if (oi >= 0 && r.start - done[oi].e <= dist) {
                Cluster& c = done[oi];
                if (r.end > c.e) c.e = r.end;
                c.recs.push_back(r);
            } else {
                Cluster c; c.open = true; c.chrom = r.chrom(); c.s = r.start; c.e = r.end; c.recs.push_back(r);
                done.push_back(std::move(c));
                openIdx[si] = (int)done.size() - 1;
            }
        }
        flushAll();
    }
    OUT.flush();
    return 0;
}
