        bamOpenReader(*bamRd, in);
        ft = FT_BAM;
    }
    return true;
}

static bool oldIsInt(const string& s) {
    if (s.empty()) return false;
    size_t i = 0;
    if (s[0] == '-') i = 1;
    if (i >= s.size()) return false;
    for (; i < s.size(); i++) if (s[i] < '0' || s[i] > '9') return false;
    return true;
}

[[noreturn]] static void stollAbort() {
    OUT.flush();
    errmsg("terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoll\n");
    fflush(stderr);
    abort();
}

static pos_t oldToPos(const string& s) {
    const char* p = s.c_str();
    while (*p == ' ' || *p == '\t') p++;
    if (!((*p >= '0' && *p <= '9') || ((*p == '-' || *p == '+') && p[1] >= '0' && p[1] <= '9'))) stollAbort();
    return strtoll(p, nullptr, 10);
}

bool OldReader::parse(const string& line, Rec& r) {
    splitTab(line, r.f);
    int n = (int)r.f.size();
    if (!typed) {
        if (n < 3) die("It looks as though you have less than 3 columns at line " + itos(lineNo) + " in file " + fn + ".  Are you sure your files are tab-delimited?\n");
        if (ft == FT_VCF) {
        } else if (oldIsInt(r.f[1]) && oldIsInt(r.f[2])) ft = FT_BED;
        else if ((n == 9 || n == 8) && oldIsInt(r.f[3]) && oldIsInt(r.f[4])) ft = FT_GFF;
        else die("Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line " + itos(lineNo) + "?\n");
        nf = n;
        typed = true;
    } else {
        if (n < 3) die("It looks as though you have less than 3 columns at line " + itos(lineNo) + " in file " + fn + ".  Are you sure your files are tab-delimited?\n");
        if (ft == FT_BED && n != nf) die("Differing number of BED fields encountered at line: " + itos(lineNo) + ".  Exiting...\n");
    }
    r.ft = ft;
    r.bk = nf;
    if (ft == FT_BED) {
        r.start = oldToPos(r.f[1]);
        r.end = oldToPos(r.f[2]);
        if (r.start > r.end) die("Error: malformed BED entry at line " + itos(lineNo) + ". Start was greater than end. Exiting.\n");
        if (r.start < 0) die("Error: malformed BED entry at line " + itos(lineNo) + ". Start Coordinate detected that is < 0. Exiting.\n");
        if (n >= 6) { r.strand = r.f[5] == "+" ? '+' : r.f[5] == "-" ? '-' : '.'; r.hasStrand = true; }
        else { r.strand = '.'; r.hasStrand = false; }
    } else if (ft == FT_GFF) {
        if (n != 8 && n != 9) return false;
        r.start = oldToPos(r.f[3]) - 1;
        r.end = oldToPos(r.f[4]);
        if (r.start > r.end) die("Error: malformed GFF entry at line " + itos(lineNo) + ". Start was greater than end. Exiting.\n");
        if (r.start < 0) die("Error: malformed GFF entry at line " + itos(lineNo) + ". Start Coordinate detected that is < 1. Exiting.\n");
        r.strand = r.f[6] == "+" ? '+' : r.f[6] == "-" ? '-' : '.';
        r.hasStrand = true;
    } else if (ft == FT_VCF) {
        if (n < 8) die("It looks as though you have less than 3 columns at line " + itos(lineNo) + " in file " + fn + ".  Are you sure your files are tab-delimited?\n");
        r.start = oldToPos(r.f[1]) - 1;
        const string& ref = r.f[3];
        const string& alt = r.f[4];
        pos_t len = (pos_t)ref.size();
        if (!alt.empty() && alt[0] == '<') {
            // structural variant
            const string& info = r.f[7];
            size_t p = info.find("SVLEN=");
            size_t q = info.find("END=");
            if (q != string::npos && q > 0 && info[q - 1] != ';') q = string::npos;
            if (alt.find("INS") != string::npos) len = 0;
            else if (q != string::npos) len = atoll(info.c_str() + q + 4) - r.start;
            else if (p != string::npos) { len = atoll(info.c_str() + p + 6); if (len < 0) len = -len; }
        }
        r.end = r.start + len;
        r.strand = '.';
        r.hasStrand = false;
    }
    r.ostart = r.start; r.oend = r.end;
    r.zl = false;
    if (r.start == r.end) { r.zl = true; r.start -= 1; r.end += 1; }
    return true;
}

bool OldReader::next(Rec& r) {
    if (isBam) return bamNextRec(*bamRd, r);
    string line;
    while (in.getline(line)) {
        lineNo++;
        if (line.empty()) continue;
        if (line[0] == '#' || startsWith(line, "track") || startsWith(line, "browser")) {
            if (startsWith(line, "##fileformat=VCF")) ft = FT_VCF;
            if (!headerDone) header.push_back(line);
            continue;
        }
        headerDone = true;
        if (!parse(line, r)) continue;
        return true;
    }
    return false;
}

void appendOldCoords(string& o, const Rec& r, pos_t s, pos_t e) {
    appendRecCoords(o, r, s, e);
}

void appendOld(string& o, const Rec& r) {
    if (r.zl) appendRecCoords(o, r, r.start + 1, r.end - 1);
    else appendRecCoords(o, r, r.start, r.end);
}

void loadOld(const string& fn, vector<Rec>& v, OldReader* rd) {
    OldReader tmp;
    OldReader& R = rd ? *rd : tmp;
    R.open(fn);
    Rec r;
    while (R.next(r)) v.push_back(r);
}
