// bedtools sort
#include "oldbed.h"
#include "tools.h"
#include <unistd.h>

static bool byStart(const Rec& a, const Rec& b) { return a.start < b.start; }
static bool bySizeA(const Rec& a, const Rec& b) { return (a.end - a.start) < (b.end - b.start); }
static bool bySizeD(const Rec& a, const Rec& b) { return (a.end - a.start) > (b.end - b.start); }
static string scoreOf(const Rec& r) {
    if (r.ft == FT_GFF) return r.f.size() > 5 ? r.f[5] : "";
    return r.f.size() > 4 ? r.f[4] : "";
}

int main_sort(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn, gfile;
    bool haveI = false, header = false;
    int mode = 0, nmodes = 0;
    bool useG = false;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("sort");
        if (s == "-i") { if (i + 1 < a.size()) { fn = a[++i]; haveI = true; } }
        else if (s == "-sizeA") { mode = 1; nmodes++; }
        else if (s == "-sizeD") { mode = 2; nmodes++; }
        else if (s == "-chrThenSizeA") { mode = 3; nmodes++; }
        else if (s == "-chrThenSizeD") { mode = 4; nmodes++; }
        else if (s == "-chrThenScoreA") { mode = 5; nmodes++; }
        else if (s == "-chrThenScoreD") { mode = 6; nmodes++; }
        else if (s == "-g" || s == "-faidx") { if (i + 1 < a.size()) { gfile = a[++i]; useG = true; nmodes++; } }
        else if (s == "-header") header = true;
        else {
            helpAndExit("sort", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
        }
    }
    if (!haveI) {
        if (isatty(0)) helpAndExit("sort");
        fn = "stdin";
    }
    if (nmodes > 1) helpAndExit("sort", "\n*****\n*****ERROR: Sorting options are mutually exclusive.  Please choose just one. \n*****\n");
    // note: help printed after error for this case
    OldReader rd;
    vector<Rec> all;
    loadOld(fn, all, &rd);
    std::map<string, vector<Rec>> byChrom;
    for (auto& r : all) byChrom[r.chrom()].push_back(std::move(r));
    for (auto& kv : byChrom) std::sort(kv.second.begin(), kv.second.end(), byStart);
    if (header) for (auto& h : rd.header) { outs(h); outnl(); }
    auto pr = [&](const Rec& r) { appendOld(OUT.buf, r); outnl(); };
    if (mode == 0 && !useG) {
        for (auto& kv : byChrom) for (auto& r : kv.second) pr(r);
    } else if (useG) {
        Genome g;
        // genome names file: first column
        InFile in;
        if (!in.open(gfile)) die("Error: The requested genome file (" + gfile + ") could not be opened. Exiting!\n");
        string line; vector<string> f;
        vector<string> order;
        std::set<string> seen;
        while (in.getline(line)) {
            if (line.empty()) continue;
            splitTab(line, f);
            if (!seen.count(f[0])) { seen.insert(f[0]); order.push_back(f[0]); }
        }
        for (auto& kv : byChrom) if (!seen.count(kv.first)) die("Chromosome \"" + kv.first + "\" undefined in " + gfile + "\n");
        for (auto& c : order) {
            auto it = byChrom.find(c);
            if (it == byChrom.end()) continue;
            for (auto& r : it->second) pr(r);
        }
    } else if (mode == 1 || mode == 2) {
        vector<Rec> v;
        for (auto& kv : byChrom) for (auto& r : kv.second) v.push_back(r);
        std::sort(v.begin(), v.end(), mode == 1 ? bySizeA : bySizeD);
        for (auto& r : v) pr(r);
    } else if (mode == 3 || mode == 4) {
        for (auto& kv : byChrom) {
            vector<Rec> v = kv.second;
            std::sort(v.begin(), v.end(), mode == 3 ? bySizeA : bySizeD);
            for (auto& r : v) pr(r);
        }
    } else {
        for (auto& kv : byChrom) {
            vector<Rec> v = kv.second;
            if (mode == 5) std::sort(v.begin(), v.end(), [](const Rec& x, const Rec& y) { return scoreOf(x) < scoreOf(y); });
            else std::sort(v.begin(), v.end(), [](const Rec& x, const Rec& y) { return scoreOf(x) > scoreOf(y); });
            for (auto& r : v) pr(r);
        }
    }
    OUT.flush();
    return 0;
}
EOF"}

