    if (header) for (auto& h : rd.header) { outs(h); outnl(); }
    auto pr = [&](const Rec& r) { appendOld(OUT.buf, r); outnl(); };
    if (mode == 0 && !useG) {
        for (auto& kv : byChrom) for (auto& r : kv.second) pr(r);
    } else if (useG) {
        Genome g;
        // genome names file: first column
        InFile in;
        if (!in.open(gfile)) die("Error: The requested genome file (" + gfile + ") could not be opened. Exiting!\n");
        string line; vector<string> f;
        vector<string> order;
        std::set<string> seen;
        while (in.getline(line)) {
            if (line.empty()) continue;
            splitTab(line, f);
            if (!seen.count(f[0])) { seen.insert(f[0]); order.push_back(f[0]); }
        }
        for (auto& kv : byChrom) if (!seen.count(kv.first)) die("Chromosome \"" + kv.first + "\" undefined in " + gfile + "\n");
        for (auto& c : order) {
            auto it = byChrom.find(c);
            if (it == byChrom.end()) continue;
            for (auto& r : it->second) pr(r);
        }
    } else if (mode == 1 || mode == 2) {
        vector<Rec> v;
        for (auto& kv : byChrom) for (auto& r : kv.second) v.push_back(r);
        std::sort(v.begin(), v.end(), mode == 1 ? bySizeA : bySizeD);
        for (auto& r : v) pr(r);
    } else if (mode == 3 || mode == 4) {
        for (auto& kv : byChrom) {
            vector<Rec> v = kv.second;
            std::sort(v.begin(), v.end(), mode == 3 ? bySizeA : bySizeD);
            for (auto& r : v) pr(r);
        }
    } else {
        for (auto& kv : byChrom) {
            vector<Rec> v = kv.second;
            if (mode == 5) std::sort(v.begin(), v.end(), [](const Rec& x, const Rec& y) { return scoreOf(x) < scoreOf(y); });
            else std::sort(v.begin(), v.end(), [](const Rec& x, const Rec& y) { return scoreOf(x) > scoreOf(y); });
            for (auto& r : v) pr(r);
        }
    }
    OUT.flush();
    return 0;
}
EOF

