// bedtools slop, flank, shift
#include "oldbed.h"
#include "tools.h"
#include <unistd.h>

namespace {
struct SFArgs {
    string fn, gfile;
    bool haveI = false, haveG = false, haveB = false, haveL = false, haveR = false;
    bool haveS = false, haveP = false, haveM = false;
    double b = 0, l = 0, r = 0, s = 0, p = 0, m = 0;
    bool strand = false, pct = false, header = false;
};
}

static void parseSF(const string& tool, int argc, char** argv, SFArgs& A) {
    vector<string> a(argv + 2, argv + argc);
    bool isShift = tool == "shift";
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        auto val = [&](double& d, bool& flag) { if (i + 1 < a.size()) { d = atof(a[++i].c_str()); flag = true; } };
        if (s == "-h" || s == "--help") helpAndExit(tool);
        if (s == "-i") { if (i + 1 < a.size()) { A.fn = a[++i]; A.haveI = true; } }
        else if (s == "-g") { if (i + 1 < a.size()) { A.gfile = a[++i]; A.haveG = true; } }
        else if (!isShift && s == "-b") val(A.b, A.haveB);
        else if (!isShift && s == "-l") val(A.l, A.haveL);
        else if (!isShift && s == "-r") val(A.r, A.haveR);
        else if (!isShift && s == "-s") A.strand = true;
        else if (isShift && s == "-s") val(A.s, A.haveS);
        else if (isShift && s == "-p") val(A.p, A.haveP);
        else if (isShift && s == "-m") val(A.m, A.haveM);
        else if (s == "-pct") A.pct = true;
        else if (s == "-header") A.header = true;
        else errHelpExit(tool, "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    if (!A.haveI) {
        if (!isatty(0)) { A.fn = "stdin"; A.haveI = true; }
    }
    bool err = false;
    auto msg = [&](const string& m) { errmsg("\n*****\n*****ERROR: " + m + " \n*****\n"); err = true; };
