    if (!haveI) helpAndExit("complement", "***** ERROR: No input file given. Exiting. *****\n");
    OUT.setNewApi();
    Genome g; g.load(gfile);
    RecReader rd; rd.open(fn);
    int gi = -1;              // index of current chrom in genome
    pos_t curEnd = 0;
    pos_t prevStart = -1;
    string& ob = OUT.buf;
    auto emit = [&](const string& c, pos_t s, pos_t e) {
        ob += c; ob += '\t'; ob += itos(s); ob += '\t'; ob += itos(e); outnl();
    };
    auto finishChrom = [&](int idx) {
        const string& c = g.names[idx];
        pos_t cs = g.sizes[c];
        if (curEnd < cs) emit(c, curEnd, cs);
    };
    Rec r;
    while (rd.next(r)) {
        int k = g.idx(r.chrom());
        if (k < 0) die("Error: requested chromosome " + r.chrom() + " does not exist in the genome file " + gfile + ". Exiting.\n");
        if (k != gi) {
            if (k < gi) {
                string l; appendRecCoords(l, r, r.start, r.end);
                die("Error: Sorted input specified, but the file " + fn + " has the following record with a different sort order than the genomeFile " + gfile + "\n" + l + "\n");
            }
            if (gi >= 0) finishChrom(gi);
            if (!limit) for (int j = gi + 1; j < k; j++) emit(g.names[j], 0, g.sizes[g.names[j]]);
            gi = k; curEnd = 0; prevStart = -1;
        }
        if (r.start < prevStart) {
            string l; appendRecCoords(l, r, r.start, r.end);
            die("Error: Sorted input specified, but the file " + fn + " has the following out of order record\n" + l + "\n");
        }
        prevStart = r.start;
        pos_t cs = g.sizes[r.chrom()];
        if (r.end > cs) {
            errmsg("***** WARNING: " + r.chrom() + ":" + itos(r.start) + "-" + itos(r.end) + " exceeds the length of chromosome (" + r.chrom() + ")\n");
        }
        if (r.start > curEnd) { emit(r.chrom(), curEnd, r.start); }
        else if (r.start != curEnd && r.start < curEnd) {}
        if (r.start != curEnd && r.start < 0 && curEnd == 0) emit(r.chrom(), curEnd, r.start);
        if (r.end > curEnd) curEnd = r.end;
    }
    if (gi >= 0) finishChrom(gi);
    if (!limit) for (int j = gi + 1; j < (int)g.names.size(); j++) emit(g.names[j], 0, g.sizes[g.names[j]]);
    OUT.flush();
    return 0;
}

int main_makewindows(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string gfile, bfile, idm;
    bool haveG = false, haveB = false, haveW = false, haveS = false, haveN = false, reverse = false;
    uint32_t w = 0, st = 0, n = 0;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("makewindows");
        if (s == "-g") { if (i + 1 < a.size()) { gfile = a[++i]; haveG = true; } }
        else if (s == "-b") { if (i + 1 < a.size()) { bfile = a[++i]; haveB = true; } }
        else if (s == "-w") { if (i + 1 < a.size()) { w = (uint32_t)atol(a[++i].c_str()); haveW = true; } }
        else if (s == "-s") { if (i + 1 < a.size()) { st = (uint32_t)atol(a[++i].c_str()); haveS = true; } }
        else if (s == "-n") { if (i + 1 < a.size()) { n = (uint32_t)atol(a[++i].c_str()); haveN = true; } }
        else if (s == "-i") {
            if (i + 1 < a.size()) {
                idm = a[++i];
                if (idm != "src" && idm != "winnum" && idm != "srcwinnum")
                    errHelpExit("makewindows", "\n*****ERROR: Invalid ID method (" + idm + "). Possible values are: winnum, srcwinnum\n\n\n");
            }
        }
        else if (s == "-reverse") reverse = true;
        else errHelpExit("makewindows", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    auto err = [&](const string& m) { errHelpExit("makewindows", "\n*****\n*****ERROR: " + m + "\n*****\n"); };
    if (haveG && haveB) err("Can't combine -g (genome file) and -b (BED file). Please use one or the other.");
    if (!haveG && !haveB) err("Need -g (genome file) or -b (BED file) for interval source. ");
    if (haveW && haveN) err("Can't combine -w (window size) and -n (number of windows). Please use one or the other. ");
    if (!haveW && !haveN) err("Need -w (window size) or -n (number of windows). ");
    if (haveW && !haveS) st = w;
    if (haveW && st == 0) err("The step (-s) option must be greater than zero. ");
    string& ob = OUT.buf;
    auto process = [&](const string& chrom, pos_t start, pos_t end, const string& name) {
        auto emit = [&](pos_t s, pos_t e, pos_t num) {
            ob += chrom; ob += '\t'; ob += itos(s); ob += '\t'; ob += itos(e);
            if (idm == "src") { ob += '\t'; ob += name; }
            else if (idm == "winnum") { ob += '\t'; ob += itos(num); }
            else if (idm == "srcwinnum") { ob += '\t'; ob += name; ob += '_'; ob += itos(num); }
            outnl();
        };
        if (haveW) {
            vector<std::pair<pos_t, pos_t>> v;
            for (pos_t s = start; s < end; s += st) {
                pos_t e = s + (pos_t)w; if (e > end) e = end;
                v.push_back({s, e});
            }
            pos_t cnt = v.size();
            for (pos_t i = 0; i < cnt; i++) emit(v[i].first, v[i].second, reverse ? cnt - i : i + 1);
        } else {
            if (n == 0) { OUT.flush(); raise(SIGFPE); }
            pos_t len = end - start;
            if (len < (pos_t)n) {
                errmsg("WARNING: Interval " + chrom + ":" + itos(start) + "-" + itos(end) + " is smaller than the number of windows requested. Skipping.\n");
                return;
            }
            pos_t ws = len / n;
            for (pos_t i = 0; i < (pos_t)n; i++) {
                pos_t s = start + i * ws;
                pos_t e = (i == (pos_t)n - 1) ? end : s + ws;
                emit(s, e, reverse ? n - i : i + 1);
            }
        }
    };
    if (haveG) {
        InFile in;
        if (!in.open(gfile)) die("Error: Can't open genome file " + gfile + ". Exiting...\n");
        in.close();
        Genome g; g.load(gfile);
        for (auto& c : g.names) process(c, 0, g.sizes[c], c);
        process("", 0, 0, "");
    } else {
        OldReader rd; rd.open(bfile);
        Rec r;
        while (rd.next(r)) {
            pos_t s = r.zl ? r.start + 1 : r.start, e = r.zl ? r.end - 1 : r.end;
            process(r.chrom(), s, e, r.f.size() > 3 ? r.f[3] : "");
        }
    }
    OUT.flush();
    return 0;
}
