// bedtools closest
#include "overlap.h"
#include "tools.h"
#include <unistd.h>

namespace {
struct CDB {
    string fn;
    RecReader rd;
    vector<Rec> recs;
    BinIndex idx;
    std::unordered_map<string, vector<int>> byStart; // indices sorted by start (file order)
    std::unordered_map<string, vector<int>> byEnd;   // indices sorted by end
};
struct Cand {
    const Rec* r;
    pos_t absd;
    pos_t sd;      // signed distance (or unsigned)
    int section;   // 0 = preferred, 1 = rest
    long ord;      // ordering key (db, idx)
};
}

static void sortedCheck(const vector<Rec>& recs, const string& fn) {
    std::set<string> seen;
    string prev;
    pos_t ps = -1;
    for (size_t i = 0; i < recs.size(); i++) {
        const Rec& r = recs[i];
        bool bad = false;
        if (i > 0) {
            if (r.chrom() != prev) { if (seen.count(r.chrom())) bad = true; }
            else if (r.start < ps) bad = true;
        }
        if (bad) {
            string l; appendRecCoords(l, r, r.start, r.end);
            die("Error: Sorted input specified, but the file " + fn + " has the following out of order record\n" + l + "\n");
        }
        if (i == 0 || r.chrom() != prev) seen.insert(r.chrom());
        prev = r.chrom(); ps = r.start;
    }
}

