// bedtools subtract
#include "overlap.h"
#include "tools.h"

int main_subtract(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fa;
    vector<string> fbs;
    bool haveA = false, haveB = false, remAll = false, remSum = false, wb = false, wo = false, header = false;
    OvlOpts o;
    if (a.empty()) helpAndExit("subtract", "***** ERROR: No input file given. Exiting. *****\n");
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("subtract");
        if (s == "-a") { if (i + 1 >= a.size()) helpAndExit("subtract", "***** ERROR: -a option given, but no query file specified. *****\n"); fa = a[++i]; haveA = true; }
        else if (s == "-b") {
            if (i + 1 >= a.size()) helpAndExit("subtract", "***** ERROR: -b option given, but no database file specified. *****\n");
            haveB = true;
            while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-' || a[i + 1] == "-")) fbs.push_back(a[++i]);
            if (fbs.empty()) fbs.push_back(a[++i]);
        }
        else if (s == "-A") remAll = true;
        else if (s == "-N") remSum = true;
        else if (s == "-wb") wb = true;
        else if (s == "-wo") wo = true;
        else if (s == "-header") header = true;
        else if (s == "-sorted" || s == "-nonamecheck" || s == "-bed" || s == "-nobuf") {}
        else if (s == "-iobuf" || s == "-g") { if (i + 1 < a.size()) i++; }
        else if (s == "-f" || s == "-F") {
            if (i + 1 >= a.size()) helpAndExit("subtract", "***** ERROR: Unrecognized parameter: " + s + " *****\n");
            parseOvlOpt(a, i, o, "subtract");
        }
        else if (parseOvlOpt(a, i, o, "subtract")) {}
        else helpAndExit("subtract", "***** ERROR: Unrecognized parameter: " + s + " *****\n");
    }
    if (!haveA || !haveB) helpAndExit("subtract", "***** ERROR: query and database files not specified. *****\n");
    if (remSum && !o.fSet) helpAndExit("subtract", "***** ERROR: -f must be in the range (0.0, 1.0]. *****\n");
    if (o.fSet && (o.f <= 0 || o.f > 1)) helpAndExit("subtract", "***** ERROR: -f must be in the range (0.0, 1.0]. *****\n");
    if (o.FSet && (o.F <= 0 || o.F > 1)) helpAndExit("subtract", "***** ERROR: -F must be in the range (0.0, 1.0]. *****\n");
    if (o.sameStrand && o.diffStrand) helpAndExit("subtract", "***** ERROR: request -s for sameStrand, or -S for diffStrand, not both. *****\n");
    OUT.setNewApi();
    RecReader ra; ra.open(fa);
    vector<vector<Rec>*> dbr;
    vector<BinIndex*> dbi;
    for (auto& fn : fbs) {
        RecReader rd; rd.open(fn);
        auto* v = new vector<Rec>();
        Rec r;
        while (rd.next(r)) { r.db = (int)dbr.size(); v->push_back(r); }
        auto* bi = new BinIndex(); bi->build(*v);
        dbr.push_back(v); dbi.push_back(bi);
    }
    if (header) for (auto& h : ra.header) { outs(h); outnl(); }
    OvlOpts o2 = o;
    if (remSum) { o2.f = 1e-9; o2.fSet = false; }
    Rec ar;
    vector<int> cand;
    string& ob = OUT.buf;
    while (ra.next(ar)) {
        vector<const Rec*> hits;
        for (size_t d = 0; d < dbr.size(); d++) {
            dbi[d]->query(ar.chrom(), ar.start, ar.end, cand);
            for (int k : cand) { const Rec& br = (*dbr[d])[k]; if (hitOk(ar, br, o2)) hits.push_back(&br); }
        }
        if (remAll) { if (hits.empty()) { appendRec(ob, ar); outnl(); } continue; }
        if (remSum) {
            vector<std::pair<pos_t, pos_t>> iv;
            for (auto* h : hits) iv.push_back({std::max(h->start, ar.start), std::min(h->end, ar.end)});
            std::sort(iv.begin(), iv.end());
            pos_t cov = 0, cs = -1, ce = -1;
            for (auto& x : iv) {
                if (x.first > ce) { if (ce > cs) cov += ce - cs; cs = x.first; ce = x.second; }
                else if (x.second > ce) ce = x.second;
