            for (auto& x : iv) {
                if (x.first > ce) { if (ce > cs) cov += ce - cs; cs = x.first; ce = x.second; }
                else if (x.second > ce) ce = x.second;
            }
            if (ce > cs) cov += ce - cs;
            double ratio = (double)cov / (double)(ar.end - ar.start);
            if (!(hits.size() > 0 && ratio > o.f)) { appendRec(ob, ar); outnl(); }
            continue;
        }
        // compute remaining fragments
        vector<std::pair<pos_t, pos_t>> iv;
        for (auto* h : hits) iv.push_back({h->start, h->end});
        std::sort(iv.begin(), iv.end());
        vector<std::pair<pos_t, pos_t>> frags;
        pos_t cur = ar.start;
        for (auto& x : iv) {
            if (x.first > cur) frags.push_back({cur, std::min(x.first, ar.end)});
            if (x.second > cur) cur = x.second;
            if (cur >= ar.end) break;
        }
        if (cur < ar.end) frags.push_back({cur, ar.end});
        if (hits.empty()) {
            if (wo) {
                appendRec(ob, ar); ob += '\t'; appendRec(ob, ar); ob += '\t'; ob += itos(ar.oend - ar.ostart); outnl();
            } else if (wb) {
                appendRec(ob, ar); ob += '\t'; appendRec(ob, ar); outnl();
            } else { appendRec(ob, ar); outnl(); }
            continue;
        }
        if (ar.zl) {
            if (!frags.empty()) { appendRec(ob, ar); outnl(); }
            continue;
        }
        for (auto& fr : frags) {
            if (fr.second <= fr.first) continue;
            if (wo) {
                appendRec(ob, ar); ob += '\t';
                ob += ar.chrom(); ob += '\t'; ob += itos(fr.first); ob += '\t'; ob += itos(fr.second);
                for (int k = 3; k < ar.nf(); k++) ob += '\t';
                ob += '\t'; ob += itos(fr.second - fr.first); outnl();
            } else if (wb) {
                appendRecCoords(ob, ar, fr.first, fr.second); ob += '\t';
                ob += ar.chrom(); ob += '\t'; ob += itos(fr.first); ob += '\t'; ob += itos(fr.second);
                for (int k = 3; k < ar.nf(); k++) ob += '\t';
                outnl();
            } else {
                appendRecCoords(ob, ar, fr.first, fr.second); outnl();
            }
        }
    }
    OUT.flush();
    return 0;
}
