            for (pos_t i = 0; i < len; i++) if (counted(i)) tot += dep[i];
            appendRec(ob, ar); ob += '\t'; ob += fmtFixed(lenA > 0 ? tot / lenA : 0.0, 7); outnl();
            continue;
        }
        if (hist) {
            std::map<pos_t, pos_t> h;
            for (pos_t i = 0; i < len; i++) if (counted(i)) h[dep[i]]++;
            for (auto& kv : h) {
                appendRec(ob, ar); ob += '\t'; ob += itos(kv.first); ob += '\t'; ob += itos(kv.second); ob += '\t';
                ob += itos(lenA); ob += '\t'; ob += fmtFixed((double)kv.second / lenA, 7); outnl();
                allHist[kv.first] += kv.second;
            }
            allLen += lenA;
            continue;
        }
        pos_t covered = 0;
        for (pos_t i = 0; i < len; i++) if (counted(i) && dep[i] > 0) covered++;
        appendRec(ob, ar); ob += '\t'; ob += itos(hits.size()); ob += '\t'; ob += itos(covered); ob += '\t';
        ob += itos(lenA); ob += '\t'; ob += fmtFixed(lenA > 0 ? (double)covered / lenA : 0.0, 7); outnl();
    }
    if (hist) {
        for (auto& kv : allHist) {
            ob += "all\t"; ob += itos(kv.first); ob += '\t'; ob += itos(kv.second); ob += '\t'; ob += itos(allLen); ob += '\t';
            ob += fmtFixed((double)kv.second / allLen, 7); outnl();
        }
    }
    OUT.flush();
    return 0;
}
