        if (counts) { appendRec(ob, ar); ob += '\t'; ob += itos(hits.size()); outnl(); continue; }
        pos_t s = ar.start, e = ar.end;
        pos_t len = e - s;
        dep.assign(len > 0 ? len : 0, 0);
        vector<std::pair<pos_t, pos_t>> blocks;
        for (auto* h : hits) {
            if (o.split) getBlocks(*h, blocks);
            else { blocks.clear(); blocks.push_back({h->start, h->end}); }
            for (auto& b : blocks) {
                pos_t bs = std::max(b.first, s), be = std::min(b.second, e);
                for (pos_t p = bs; p < be; p++) dep[p - s]++;
            }
        }
        // for split A, only count A's blocks
        vector<char> inA;
        pos_t lenA = len;
        if (o.split && ar.ft == FT_BED && ar.f.size() >= 12) {
            vector<std::pair<pos_t, pos_t>> ab; getBlocks(ar, ab);
            inA.assign(len, 0);
            lenA = 0;
            for (auto& b : ab) for (pos_t p = std::max(b.first, s); p < std::min(b.second, e); p++) { if (!inA[p - s]) { inA[p - s] = 1; lenA++; } }
        }
        auto counted = [&](pos_t i) { return inA.empty() || inA[i]; };
        if (depth) {
            for (pos_t i = 0; i < len; i++) {
                if (!counted(i)) continue;
                appendRec(ob, ar); ob += '\t'; ob += itos(i + 1); ob += '\t'; ob += itos(dep[i]); outnl();
            }
            continue;
        }
        if (mean) {
            double tot = 0;
            for (pos_t i = 0; i < len; i++) if (counted(i)) tot += dep[i];
            appendRec(ob, ar); ob += '\t'; ob += fmtFixed(lenA > 0 ? tot / lenA : 0.0, 7); outnl();
            continue;
        }
        if (hist) {
            std::map<pos_t, pos_t> h;
            for (pos_t i = 0; i < len; i++) if (counted(i)) h[dep[i]]++;
            for (auto& kv : h) {
                appendRec(ob, ar); ob += '\t'; ob += itos(kv.first); ob += '\t'; ob += itos(kv.second); ob += '\t';
                ob += itos(lenA); ob += '\t'; ob += fmtFixed((double)kv.second / lenA, 7); outnl();
                allHist[kv.first] += kv.second;
            }
            allLen += lenA;
            continue;
        }
        pos_t covered = 0;
        for (pos_t i = 0; i < len; i++) if (counted(i) && dep[i] > 0) covered++;
        appendRec(ob, ar); ob += '\t'; ob += itos(hits.size()); ob += '\t'; ob += itos(covered); ob += '\t';
        ob += itos(lenA); ob += '\t'; ob += fmtFixed(lenA > 0 ? (double)covered / lenA : 0.0, 7); outnl();
    }
    if (hist) {
        for (auto& kv : allHist) {
            ob += "all\t"; ob += itos(kv.first); ob += '\t'; ob += itos(kv.second); ob += '\t'; ob += itos(allLen); ob += '\t';
            ob += fmtFixed((double)kv.second / allLen, 7); outnl();
        }
    }
    OUT.flush();
    return 0;
}
