// bedtools genomecov
#include "oldbed.h"
#include "tools.h"
#include <climits>

namespace {
struct GC {
    bool d = false, dz = false, bg = false, bga = false, split = false, hasStrand = false;
    char strand = 0;
    bool five = false, three = false, trackline = false;
    string trackopts;
    double scale = 1.0;
    bool scaleSet = false;
    long maxD = LONG_MAX;
    bool maxSet = false;
};
}

static string fmtScaled(pos_t depth, const GC& g) {
    if (!g.scaleSet) return itos(depth);
    return fmtDefault((double)depth * g.scale);
}

int main_genomecov(int argc, char** argv) {
