        else if (s == "-bg") g.bg = true;
        else if (s == "-bga") g.bga = true;
        else if (s == "-split") g.split = true;
        else if (s == "-ignoreD" || s == "-pc" || s == "-du") {}
        else if (s == "-fs") { if (i + 1 < a.size()) i++; }
        else if (s == "-strand") {
            if (i + 1 < a.size()) {
                string v = a[++i];
                if (v != "+" && v != "-") errHelpExit("genomecov", "*****ERROR: invalid -strand value (" + v + "). Allowed options are + or -\n");
