// multiinter, unionbedg
#include "oldbed.h"
#include "tools.h"
#include <unistd.h>

namespace {
struct MFile {
    string fn;
    vector<Rec> recs;
    size_t pos = 0;
};
}

static void loadSortedCheck(MFile& m) {
    OldReader rd; rd.open(m.fn);
    Rec r;
    string pc; pos_t ps = -1; long pln = 0;
    while (rd.next(r)) {
        if (!m.recs.empty() && r.chrom() == pc && r.start < ps)
            die("ERROR: input file: (" + m.fn + ") is not sorted by chrom then start.\n       The start coordinate at line " + itos(rd.lineNo) + " is less than the start at line " + itos(pln) + "\n");
        pc = r.chrom(); ps = r.start; pln = rd.lineNo;
        m.recs.push_back(r);
    }
}

static int parseMultiArgs(const string& tool, int argc, char** argv, vector<string>& files, vector<string>& names,
                          bool& header, bool& cluster, string& gfile, bool& empty, string& filler) {
    vector<string> a(argv + 2, argv + argc);
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit(tool);
        if (s == "-i") { while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-' || a[i + 1] == "-")) files.push_back(a[++i]); }
        else if (s == "-names") { while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-')) names.push_back(a[++i]); }
        else if (s == "-header") header = true;
        else if (s == "-cluster" && tool == "multiinter") cluster = true;
        else if (s == "-g") { if (i + 1 < a.size()) gfile = a[++i]; }
        else if (s == "-empty") empty = true;
        else if (s == "-filler") { if (i + 1 < a.size()) filler = a[++i]; }
        else if (s == "-examples") { helpAndExit(tool, "", 0); }
        else errHelpExit(tool, "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    return 0;
}

int main_multiinter(int argc, char** argv) {
    vector<string> files, names;
    bool header = false, cluster = false, empty = false;
    string gfile, filler = "0";
    parseMultiArgs("multiinter", argc, argv, files, names, header, cluster, gfile, empty, filler);
    if (files.empty()) helpAndExit("multiinter", "Error: missing file names (-i) to combine.\n");
    if (files.size() == 1) die("Error: Only a single file was specified. Nothing to combine, exiting.\n");
    if (!names.empty() && names.size() != files.size()) die("Error: The number of file titles (-names) does not match the number of files (-i).\n");
    if (empty && gfile.empty()) die("Error: when using -empty, the genome sizes file (-g) must be specified using '-g FILE'.\n");
    Genome g;
    if (empty) g.load(gfile);
    vector<MFile> M(files.size());
    for (size_t i = 0; i < files.size(); i++) { M[i].fn = files[i]; loadSortedCheck(M[i]); }
    string& ob = OUT.buf;
    size_t nf = files.size();
    auto label = [&](size_t i) { return names.empty() ? itos(i + 1) : names[i]; };
    if (header) {
        ob += "chrom\tstart\tend\tnum\tlist";
        for (size_t i = 0; i < nf; i++) { ob += '\t'; ob += names.empty() ? files[i] : names[i]; }
        outnl();
    }
    struct Seg { pos_t s, e; vector<char> in; int n; };
    while (true) {
        string chrom; bool any = false;
        for (auto& m : M) if (m.pos < m.recs.size()) {
            const string& c = m.recs[m.pos].chrom();
            if (!any || c < chrom) { chrom = c; any = true; }
        }
        if (!any) break;
        // per file merged intervals
        vector<std::tuple<pos_t, int, int>> ev; // pos, type(+1 start/-1 end), file
        for (size_t i = 0; i < nf; i++) {
            auto& m = M[i];
            pos_t cs = -1, ce = -1;
            while (m.pos < m.recs.size() && m.recs[m.pos].chrom() == chrom) {
                const Rec& r = m.recs[m.pos++];
                if (cs < 0 || r.start > ce) {
                    if (cs >= 0) { ev.push_back({cs, 1, (int)i}); ev.push_back({ce, -1, (int)i}); }
                    cs = r.start; ce = r.end;
                } else if (r.end > ce) ce = r.end;
            }
            if (cs >= 0) { ev.push_back({cs, 1, (int)i}); ev.push_back({ce, -1, (int)i}); }
        }
        std::sort(ev.begin(), ev.end());
        vector<Seg> segs;
        vector<char> in(nf, 0);
        int n = 0;
        pos_t prev = 0; bool havePrev = false;
        size_t k = 0;
        while (k < ev.size()) {
            pos_t p = std::get<0>(ev[k]);
            if (havePrev && p > prev && n > 0) segs.push_back({prev, p, in, n});
            while (k < ev.size() && std::get<0>(ev[k]) == p) {
                int t = std::get<1>(ev[k]), f = std::get<2>(ev[k]);
                if (t > 0) { if (!in[f]) { in[f] = 1; n++; } }
                else { if (in[f]) { in[f] = 0; n--; } }
                k++;
            }
            prev = p; havePrev = true;
        }
        auto emit = [&](pos_t s, pos_t e, const vector<char>* v, int cnt) {
            ob += chrom; ob += '\t'; ob += itos(s); ob += '\t'; ob += itos(e); ob += '\t'; ob += itos(cnt); ob += '\t';
            if (!v) { ob += "none"; for (size_t i = 0; i < nf; i++) ob += "\t0"; outnl(); return; }
            bool first = true;
            for (size_t i = 0; i < nf; i++) if ((*v)[i]) { if (!first) ob += ','; ob += label(i); first = false; }
            for (size_t i = 0; i < nf; i++) { ob += '\t'; ob += (*v)[i] ? '1' : '0'; }
            outnl();
        };
        auto superset = [&](const Seg& a, const Seg& b) { // a ⊇ b
            for (size_t i = 0; i < nf; i++) if (b.in[i] && !a.in[i]) return false;
            return true;
        };
        pos_t last = 0;
        for (size_t i = 0; i < segs.size(); i++) {
            const Seg& sg = segs[i];
            if (empty && sg.s > last) emit(last, sg.s, nullptr, 0);
            last = sg.e;
            if (cluster) {
                bool prevSup = i > 0 && segs[i - 1].e == sg.s && superset(segs[i - 1], sg);
                bool nextSup = i + 1 < segs.size() && segs[i + 1].s == sg.e && superset(segs[i + 1], sg);
                if (prevSup || nextSup) continue;
            }
            emit(sg.s, sg.e, &sg.in, sg.n);
        }
        if (empty && g.has(chrom) && last < g.size(chrom)) emit(last, g.size(chrom), nullptr, 0);
    }
    OUT.flush();
    return 0;
}

