int main_annotate(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn;
    vector<string> files, names;
    bool haveI = false, counts = false, both = false, s = false, S = false;
    for (size_t i = 0; i < a.size(); i++) {
        const string& x = a[i];
