        if (x == "-i") { if (i + 1 < a.size()) { fn = a[++i]; haveI = true; } }
        else if (x == "-files") { while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-' || a[i + 1] == "-")) files.push_back(a[++i]); }
        else if (x == "-names") { while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-')) names.push_back(a[++i]); }
        else if (x == "-counts") counts = true;
        else if (x == "-both") both = true;
        else if (x == "-s") s = true;
        else if (x == "-S") S = true;
        else errHelpExit("annotate", "\n*****ERROR: Unrecognized parameter: " + x + " *****\n\n");
    }
    if (!haveI || files.empty()) errHelpExit("annotate", "\n*****\n*****ERROR: Need -i and -files files. \n*****\n");
    // load A grouped by chrom (insertion order within chrom)
    OldReader ra; ra.open(fn);
    std::map<string, vector<Rec>> A;
    Rec r;
    size_t nfA = 0;
    while (ra.next(r)) { if (!nfA) nfA = r.f.size(); A[r.chrom()].push_back(r); }
    vector<vector<Rec>> B(files.size());
    vector<BinIndex> idx(files.size());
    for (size_t i = 0; i < files.size(); i++) { loadOld(files[i], B[i]); idx[i].build(B[i]); }
    string& ob = OUT.buf;
    if (!names.empty()) {
        ob += '#';
        for (size_t k = 0; k < nfA; k++) ob += '\t';
        for (size_t k = 0; k < names.size(); k++) { if (k) ob += '\t'; ob += names[k]; }
        outnl();
    }
    vector<int> cand;
    for (auto& kv : A) {
        for (auto& ar : kv.second) {
            appendOld(ob, ar);
            for (size_t i = 0; i < files.size(); i++) {
                idx[i].query(ar.chrom(), ar.start, ar.end, cand);
                size_t cnt = 0;
                vector<std::pair<pos_t, pos_t>> iv;
                for (int k : cand) {
                    const Rec& br = B[i][k];
                    if (s && !(ar.strand != '.' && br.strand != '.' && ar.strand == br.strand)) continue;
                    if (S && !(ar.strand != '.' && br.strand != '.' && ar.strand != br.strand)) continue;
                    cnt++;
                    pos_t bs = br.zl ? br.start + 1 : br.start, be = br.zl ? br.end - 1 : br.end;
                    bs = std::max(bs, ar.start); be = std::min(be, ar.end);
