                pos_t cov = 0, cs = -1, ce = -1;
                for (auto& x : iv) {
                    if (x.first > ce) { if (ce > cs) cov += ce - cs; cs = x.first; ce = x.second; }
                    else if (x.second > ce) ce = x.second;
                }
                if (ce > cs) cov += ce - cs;
                pos_t len = ar.end - ar.start;
                float frac = len > 0 ? (float)cov / (float)len : 0.0f;
                if (both) { ob += '\t'; ob += itos(cnt); ob += '\t'; ob += fmtFixed(frac, 6); }
