// jaccard, fisher, reldist
#include "overlap.h"
#include "oldbed.h"
#include "tools.h"

void sortedCheckRecs(const vector<Rec>& recs, const string& fn);

namespace {
struct MI { string chrom; pos_t s, e; char strand; };
}

// merge sorted records; if byStrand, merge per strand (dropping unstranded)
static vector<Rec> mergeRecs(const vector<Rec>& v, bool byStrand) {
    vector<Rec> out;
    if (!byStrand) {
        for (auto& r : v) {
            if (!out.empty() && out.back().chrom() == r.chrom() && r.start <= out.back().end) {
                if (r.end > out.back().end) out.back().end = r.end;
            } else {
                Rec m; m.f = {r.chrom()}; m.start = r.start; m.end = r.end; m.strand = '.'; m.ft = FT_BED;
                out.push_back(m);
            }
        }
        return out;
    }
    // per chromosome, per strand clusters in creation order
    size_t i = 0;
    while (i < v.size()) {
        size_t j = i;
        while (j < v.size() && v[j].chrom() == v[i].chrom()) j++;
        int open[2] = {-1, -1};
        for (size_t k = i; k < j; k++) {
            const Rec& r = v[k];
            if (r.strand != '+' && r.strand != '-') continue;
            int si = r.strand == '+' ? 0 : 1;
            if (open[si] >= 0 && r.start <= out[open[si]].end) {
                if (r.end > out[open[si]].end) out[open[si]].end = r.end;
            } else {
                Rec m; m.f = {r.chrom()}; m.start = r.start; m.end = r.end; m.strand = r.strand; m.ft = FT_BED;
                out.push_back(m);
                open[si] = (int)out.size() - 1;
            }
        }
        i = j;
    }
    return out;
}

static bool parseStatArgs(const string& tool, int argc, char** argv, string& fa, string& fb, string& gfile, OvlOpts& o, bool& mergeOpt) {
    vector<string> a(argv + 2, argv + argc);
    bool haveA = false, haveB = false;
    if (a.empty()) helpAndExit(tool, "***** ERROR: No input file given. Exiting. *****\n");
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit(tool);
        if (s == "-a") { if (i + 1 >= a.size()) helpAndExit(tool, "***** ERROR: -a option given, but no query file specified. *****\n"); fa = a[++i]; haveA = true; }
        else if (s == "-b") { if (i + 1 >= a.size()) helpAndExit(tool, "***** ERROR: -b option given, but no database file specified. *****\n"); fb = a[++i]; haveB = true; }
        else if (s == "-g") { if (i + 1 < a.size()) gfile = a[++i]; }
        else if (s == "-m" && tool == "fisher") mergeOpt = true;
        else if (s == "-S" && tool == "jaccard") helpAndExit(tool, "***** ERROR: -S option must be followed by + or -. *****\n");
        else if (s == "-sorted" || s == "-nonamecheck" || s == "-bed" || s == "-nobuf" || s == "-header") {}
        else if (s == "-iobuf") { if (i + 1 < a.size()) i++; }
        else if (s == "-f" || s == "-F") {
            if (i + 1 >= a.size()) helpAndExit(tool, "***** ERROR: Unrecognized parameter: " + s + " *****\n");
            parseOvlOpt(a, i, o, tool);
        }
        else if (parseOvlOpt(a, i, o, tool)) {}
        else helpAndExit(tool, "***** ERROR: Unrecognized parameter: " + s + " *****\n");
    }
    if (!haveA || !haveB) helpAndExit(tool, "***** ERROR: query and database files not specified. *****\n");
    if (o.fSet && (o.f <= 0 || o.f > 1)) helpAndExit(tool, "***** ERROR: -f must be in the range (0.0, 1.0]. *****\n");
    if (o.FSet && (o.F <= 0 || o.F > 1)) helpAndExit(tool, "***** ERROR: -F must be in the range (0.0, 1.0]. *****\n");
    if (o.sameStrand && o.diffStrand) helpAndExit(tool, "***** ERROR: request -s for sameStrand, or -S for diffStrand, not both. *****\n");
    return true;
}

static void loadNew(const string& fn, vector<Rec>& v) {
    RecReader rd; rd.open(fn);
    Rec r;
    while (rd.next(r)) v.push_back(r);
}

static void intersectStats(const vector<Rec>& A, const vector<Rec>& B, const OvlOpts& o, pos_t& inter, long& n) {
    BinIndex idx; idx.build(B);
    vector<int> cand;
    inter = 0; n = 0;
    for (auto& ar : A) {
        idx.query(ar.chrom(), ar.start, ar.end, cand);
        for (int k : cand) {
            const Rec& br = B[k];
            if (!hitOk(ar, br, o)) continue;
            inter += ovlLen(ar.start, ar.end, br.start, br.end);
            n++;
        }
    }
}

int main_jaccard(int argc, char** argv) {
    string fa, fb, gfile; OvlOpts o; bool m = false;
    parseStatArgs("jaccard", argc, argv, fa, fb, gfile, o, m);
    OUT.setNewApi();
    vector<Rec> A, B;
    loadNew(fa, A); sortedCheckRecs(A, fa);
    loadNew(fb, B); sortedCheckRecs(B, fb);
    bool bs = o.sameStrand || o.diffStrand;
    vector<Rec> MA = mergeRecs(A, bs), MB = mergeRecs(B, bs);
    pos_t la = 0, lb = 0;
    for (auto& r : MA) la += r.end - r.start;
    for (auto& r : MB) lb += r.end - r.start;
    pos_t inter; long n;
    intersectStats(MA, MB, o, inter, n);
    pos_t uni = la + lb - inter;
    string& ob = OUT.buf;
    ob += "intersection\tunion\tjaccard\tn_intersections\n";
    ob += itos(inter) + "\t" + itos(uni) + "\t" + fmtDefault((double)inter / (double)uni) + "\t" + itos(n) + "\n";
    OUT.flush();
    return 0;
}

// --- Fisher's exact test (hypergeometric) ---
static double lbinom(long n, long k) {
    if (k == 0 || n == k) return 0;
    return lgamma((double)n + 1) - lgamma((double)k + 1) - lgamma((double)(n - k) + 1);
}
static double hypergeo(long n11, long n1_, long n_1, long n) {
    return exp(lbinom(n1_, n11) + lbinom(n - n1_, n_1 - n11) - lbinom(n, n_1));
}
namespace { struct HG { long n11, n1_, n_1, n; double p; }; }
static double hypergeo_acc(long n11, long n1_, long n_1, long n, HG* aux) {
    if (n1_ || n_1 || n) {
        aux->n11 = n11; aux->n1_ = n1_; aux->n_1 = n_1; aux->n = n;
    } else {
        if (n11 % 11 && n11 + aux->n - aux->n1_ - aux->n_1) {
            if (n11 == aux->n11 + 1) {
                aux->p *= (double)(aux->n1_ - aux->n11) / n11 * (aux->n_1 - aux->n11) / (n11 + aux->n - aux->n1_ - aux->n_1);
                aux->n11 = n11;
                return aux->p;
            }
            if (n11 == aux->n11 - 1) {
                aux->p *= (double)aux->n11 / (aux->n1_ - n11) * (aux->n11 + aux->n - aux->n1_ - aux->n_1) / (aux->n_1 - n11);
                aux->n11 = n11;
                return aux->p;
            }
        }
        aux->n11 = n11;
    }
    aux->p = hypergeo(aux->n11, aux->n1_, aux->n_1, aux->n);
    return aux->p;
}
static double fisherExact(long n11, long n12, long n21, long n22, double* _left, double* _right, double* two) {
    long i, j, max, min;
    double p, q, left, right;
    HG aux;
    long n1_ = n11 + n12, n_1 = n11 + n21, n = n11 + n12 + n21 + n22;
    max = (n_1 < n1_) ? n_1 : n1_;
    min = n1_ + n_1 - n;
    if (min < 0) min = 0;
    *two = *_left = *_right = 1.;
    if (min == max) return 1.;
    q = hypergeo_acc(n11, n1_, n_1, n, &aux);
    p = hypergeo_acc(min, 0, 0, 0, &aux);
    for (left = 0., i = min + 1; p < 0.99999999 * q; ++i) left += p, p = hypergeo_acc(i, 0, 0, 0, &aux);
    --i;
    if (p < 1.00000001 * q) left += p; else --i;
    p = hypergeo_acc(max, 0, 0, 0, &aux);
    for (right = 0., j = max - 1; p < 0.99999999 * q; --j) right += p, p = hypergeo_acc(j, 0, 0, 0, &aux);
    ++j;
    if (p < 1.00000001 * q) right += p; else ++j;
    *two = left + right;
    if (*two > 1.) *two = 1.;
    if (labs(i - n11) < labs(j - n11)) right = 1. - left + q;
    else left = 1.0 - right + q;
    *_left = left; *_right = right;
    return q;
}

int main_fisher(int argc, char** argv) {
    string fa, fb, gfile; OvlOpts o; bool mergeOpt = false;
    parseStatArgs("fisher", argc, argv, fa, fb, gfile, o, mergeOpt);
    OUT.setNewApi();
    Genome g;
    if (gfile.empty()) helpAndExit("fisher", "***** ERROR: No genome file given. Exiting. *****\n");
    g.load(gfile);
    vector<Rec> A, B;
    loadNew(fa, A); sortedCheckRecs(A, fa);
    loadNew(fb, B); sortedCheckRecs(B, fb);
    if (mergeOpt) {
        bool bs = o.sameStrand || o.diffStrand;
        A = mergeRecs(A, bs); B = mergeRecs(B, bs);
    }
    pos_t la = 0, lb = 0;
    for (auto& r : A) la += r.end - r.start;
    for (auto& r : B) lb += r.end - r.start;
    pos_t inter; long nOv;
    intersectStats(A, B, o, inter, nOv);
    pos_t gsize = 0;
    for (auto& c : g.names) gsize += g.sizes[c];
    long nA = (long)A.size(), nB = (long)B.size();
    double meanA = 1.0 + (double)la / nA, meanB = 1.0 + (double)lb / nB;
    long possible = (long)((double)gsize / (meanA + meanB));
    long n11 = nOv;
    long n12 = std::max(0L, nA - n11);
    long n21 = std::max(0L, nB - n11);
    long n22 = std::max(0L, possible - n11 - n12 - n21);
    double left, right, two;
    fisherExact(n11, n12, n21, n22, &left, &right, &two);
    double ratio = ((double)n11 * (double)n22) / ((double)n12 * (double)n21);
    string& ob = OUT.buf;
    char buf[512];
    ob += "# Number of query intervals: " + itos(nA) + "\n";
    ob += "# Number of db intervals: " + itos(nB) + "\n";
    ob += "# Number of overlaps: " + itos(nOv) + "\n";
    ob += "# Number of possible intervals (estimated): " + itos(possible) + "\n";
    ob += "# phyper(" + itos(n11) + " - 1, " + itos(nA) + ", " + itos(possible) + " - " + itos(nA) + ", " + itos(nB) + ", lower.tail=F)\n";
    ob += "# Contingency Table Of Counts\n";
    ob += "#_________________________________________\n";
    ob += "#           |  in -b       | not in -b    |\n";
    snprintf(buf, sizeof buf, "#     in -a | %-12ld | %-12ld |\n", n11, n12); ob += buf;
    snprintf(buf, sizeof buf, "# not in -a | %-12ld | %-12ld |\n", n21, n22); ob += buf;
    ob += "#_________________________________________\n";
    ob += "# p-values for fisher's exact test\n";
    ob += "left\tright\ttwo-tail\tratio\n";
    snprintf(buf, sizeof buf, "%.5g\t%.5g\t%.5g\t%.4g\n", left, right, two, ratio); ob += buf;
    OUT.flush();
    return 0;
}

int main_reldist(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fa, fb;
    bool haveA = false, haveB = false, detail = false;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("reldist");
        if (s == "-a") { if (i + 1 < a.size()) { fa = a[++i]; haveA = true; } }
        else if (s == "-b") { if (i + 1 < a.size()) { fb = a[++i]; haveB = true; } }
        else if (s == "-detail") detail = true;
        else errHelpExit("reldist", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    if (!haveA || !haveB) errHelpExit("reldist", "\n*****\n*****ERROR: Need -a and -b files. \n*****\n");
    vector<Rec> B;
    loadOld(fb, B);
    std::map<string, vector<pos_t>> mids;
    for (auto& r : B) mids[r.chrom()].push_back((r.start + r.end) / 2);
    for (auto& kv : mids) std::sort(kv.second.begin(), kv.second.end());
    OldReader ra; ra.open(fa);
    Rec r;
    std::map<long, long> hist;
    long total = 0;
    string& ob = OUT.buf;
    while (ra.next(r)) {
        auto it = mids.find(r.chrom());
        if (it == mids.end()) continue;
        const vector<pos_t>& m = it->second;
        pos_t mid = (r.start + r.end) / 2;
        auto low = std::lower_bound(m.begin(), m.end(), mid);
        float rel;
        if (low != m.end() && *low == mid) rel = 0;
        else {
            if (low == m.begin() || low == m.end()) continue;
            pos_t left = *(low - 1), right = *low;
            pos_t dl = mid - left, dr = right - mid;
            rel = (float)std::min(dl, dr) / (float)(right - left);
        }
        if (detail) { appendOld(ob, r); ob += '\t'; ob += fmtFixed(rel, 3); outnl(); }
        else { hist[(long)(rel * 100)]++; total++; }
    }
    if (!detail) {
