        else if (s == "-bed") { if (i + 1 < a.size()) { bed = a[++i]; haveBed = true; } }
        else if (s == "-s") strand = true;
        else if (s == "-seq") seqOut = true;
        else if (s == "-pattern") { if (i + 1 < a.size()) { pattern = a[++i]; havePat = true; } }
        else if (s == "-C") ignoreCase = true;
        else if (s == "-fullHeader") fullHeader = true;
        else errHelpExit("nuc", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    if (!haveFi || !haveBed) errHelpExit("nuc", "");
    Fasta fa;
