    fa.writeFai(fi);
    OldReader rd; rd.open(bed);
    Rec r;
    string& ob = OUT.buf;
    bool headerDone = false;
    auto header = [&](size_t nf) {
        int c = 1;
        for (size_t k = 0; k < nf; k++) { ob += (c == 1 ? "#" : "\t"); ob += itos(c++) + "_usercol"; }
        const char* cols[] = {"pct_at", "pct_gc", "num_A", "num_C", "num_G", "num_T", "num_N", "num_oth", "seq_len"};
        for (auto* x : cols) { ob += '\t'; ob += itos(c++) + "_" + x; }
        if (seqOut) { ob += '\t'; ob += itos(c++) + "_seq"; }
        if (havePat) { ob += '\t'; ob += itos(c++) + "_user_patt_count"; }
        outnl();
        headerDone = true;
    };
    string pat = pattern;
    if (ignoreCase) for (auto& ch : pat) ch = (char)toupper((unsigned char)ch);
    while (rd.next(r)) {
        if (!headerDone) header(r.f.size());
        pos_t s = r.zl ? r.start + 1 : r.start, e = r.zl ? r.end - 1 : r.end;
        auto it = fa.seqs.find(r.chrom());
