        string seq = it->second.substr(s, e - s);
        if (strand && r.strand == '-') seq = revcomp(seq, false);
        long nA = 0, nC = 0, nG = 0, nT = 0, nN = 0, nO = 0;
        for (char ch : seq) {
            switch (toupper((unsigned char)ch)) {
                case 'A': nA++; break; case 'C': nC++; break; case 'G': nG++; break; case 'T': nT++; break; case 'N': nN++; break;
                default: nO++;
            }
        }
        double len = (double)seq.size();
        appendOld(ob, r);
        ob += '\t'; ob += fmtFixed((nA + nT) / len, 6);
        ob += '\t'; ob += fmtFixed((nG + nC) / len, 6);
        ob += '\t' + itos(nA) + '\t' + itos(nC) + '\t' + itos(nG) + '\t' + itos(nT) + '\t' + itos(nN) + '\t' + itos(nO) + '\t' + itos((pos_t)seq.size());
        if (seqOut) { ob += '\t'; ob += seq; }
        if (havePat) {
            string sq = seq;
            if (ignoreCase) for (auto& ch : sq) ch = (char)toupper((unsigned char)ch);
            long cnt = 0;
            if (!pat.empty()) { size_t p = sq.find(pat); while (p != string::npos) { cnt++; p = sq.find(pat, p + 1); } }
            ob += '\t'; ob += itos(cnt);
        }
        outnl();
    }
    if (!headerDone) header(0);
    OUT.flush();
    return 0;
}
