struct Fasta {
    vector<string> names;
    std::unordered_map<string, string> seqs;
    struct Idx { pos_t len, off, lb, lw; };
    vector<Idx> idx;
    bool load(const string& fn, bool fullHeader) {
        InFile in;
        if (!in.open(fn)) return false;
        string line, cur; bool have = false;
        pos_t off = 0;
        string* s = nullptr;
        Idx ix{0, 0, 0, 0};
        bool firstLine = true;
        // track raw line lengths for index (assumes \n endings)
        while (in.getline(line)) {
            pos_t rawlen = (pos_t)line.size() + 1;
            if (!line.empty() && line[0] == '>') {
                if (have) idx.push_back(ix);
                string h = line.substr(1);
                if (!fullHeader) {
                    size_t p = h.find_first_of(" \t");
                    if (p != string::npos) h = h.substr(0, p);
                }
                names.push_back(h);
                s = &seqs[h];
                s->clear();
                have = true;
                ix = Idx{0, off + rawlen, 0, 0};
                firstLine = true;
            } else if (s) {
                s->append(line);
                ix.len += (pos_t)line.size();
                if (firstLine) { ix.lb = (pos_t)line.size(); ix.lw = rawlen; firstLine = false; }
            }
            off += rawlen;
        }
        if (have) idx.push_back(ix);
        return true;
    }
    void writeFai(const string& fn) {
        string fai = fn + ".fai";
        if (fileExists(fai)) return;
        FILE* f = fopen(fai.c_str(), "w");
        if (!f) return;
        for (size_t i = 0; i < names.size(); i++)
            fprintf(f, "%s\t%lld\t%lld\t%lld\t%lld\n", names[i].c_str(), idx[i].len, idx[i].off, idx[i].lb, idx[i].lw);
        fclose(f);
    }
};
}

static string revcomp(const string& s, bool rna) {
    string r(s.rbegin(), s.rend());
    for (auto& c : r) {
        switch (c) {
            case 'A': c = rna ? 'U' : 'T'; break;
            case 'a': c = rna ? 'u' : 't'; break;
            case 'T': c = 'A'; break; case 't': c = 'a'; break;
            case 'U': c = 'A'; break; case 'u': c = 'a'; break;
            case 'G': c = 'C'; break; case 'g': c = 'c'; break;
            case 'C': c = 'G'; break; case 'c': c = 'g'; break;
            default: break;
        }
    }
    return r;
}

static string recName(const Rec& r) {
    if (r.ft == FT_GFF) return r.f[2];
    return r.f.size() > 3 ? r.f[3] : "";
}

