// random, shuffle, sample
#include "oldbed.h"
#include "overlap.h"
#include "tools.h"
#include <random>
#include <unistd.h>
#include <ctime>

static unsigned long long autoSeed() { return (unsigned long long)time(nullptr) + (unsigned long long)getpid(); }

int main_random(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string gfile;
    bool haveG = false, haveSeed = false;
    pos_t len = 100, n = 1000000;
    unsigned long long seed = 0;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("random");
        if (s == "-g") { if (i + 1 < a.size()) { gfile = a[++i]; haveG = true; } }
        else if (s == "-l") { if (i + 1 < a.size()) len = atoll(a[++i].c_str()); }
        else if (s == "-n") { if (i + 1 < a.size()) n = atoll(a[++i].c_str()); }
        else if (s == "-seed") { if (i + 1 < a.size()) { seed = strtoull(a[++i].c_str(), nullptr, 10); haveSeed = true; } }
        else errHelpExit("random", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    if (!haveG) errHelpExit("random", "\n*****\n*****ERROR: Need a genome (-g) file. \n*****\n");
    Genome g; g.load(gfile);
    std::mt19937_64 rng(haveSeed ? seed : autoSeed());
    unsigned long long gsize = 0;
    vector<pos_t> offs;
    for (auto& c : g.names) { offs.push_back((pos_t)gsize); gsize += g.sizes[c]; }
    string& ob = OUT.buf;
    for (pos_t i = 1; i <= n; i++) {
        pos_t start; size_t k;
        while (true) {
            unsigned long long p = rng() % gsize;
            k = std::upper_bound(offs.begin(), offs.end(), (pos_t)p) - offs.begin() - 1;
            start = (pos_t)p - offs[k];
            if (start + len <= g.sizes[g.names[k]]) break;
        }
        char strand = (rng() % 2 == 0) ? '-' : '+';
        ob += g.names[k]; ob += '\t'; ob += itos(start); ob += '\t'; ob += itos(start + len); ob += '\t';
        ob += itos(i); ob += '\t'; ob += itos(len); ob += '\t'; ob += strand;
        outnl();
    }
    OUT.flush();
    return 0;
}

int main_shuffle(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn, gfile, excl, incl;
    bool haveI = false, haveG = false, haveSeed = false, haveExcl = false, haveIncl = false;
    bool sameChrom = false, chromFirst = false, bedpe = false, noOverlap = false, beyond = false;
    double frac = 1e-9;
    long maxTries = 1000;
    unsigned long long seed = 0;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("shuffle");
        if (s == "-i") { if (i + 1 < a.size()) { fn = a[++i]; haveI = true; } }
        else if (s == "-g") { if (i + 1 < a.size()) { gfile = a[++i]; haveG = true; } }
        else if (s == "-excl") { if (i + 1 < a.size()) { excl = a[++i]; haveExcl = true; } }
        else if (s == "-incl") { if (i + 1 < a.size()) { incl = a[++i]; haveIncl = true; } }
        else if (s == "-chrom") sameChrom = true;
        else if (s == "-chromFirst") chromFirst = true;
        else if (s == "-bedpe") bedpe = true;
        else if (s == "-noOverlapping") noOverlap = true;
        else if (s == "-allowBeyondChromEnd") beyond = true;
        else if (s == "-f") { if (i + 1 < a.size()) frac = atof(a[++i].c_str()); }
        else if (s == "-maxTries") { if (i + 1 < a.size()) maxTries = atol(a[++i].c_str()); }
        else if (s == "-seed") { if (i + 1 < a.size()) { seed = strtoull(a[++i].c_str(), nullptr, 10); haveSeed = true; } }
        else errHelpExit("shuffle", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    (void)bedpe;
    if (!haveI && !isatty(0)) { fn = "stdin"; haveI = true; }
    if (!haveI || !haveG) errHelpExit("shuffle", "\n*****\n*****ERROR: Need both a BED (-i) and a genome (-g) file. \n*****\n");
    Genome g; g.load(gfile);
    std::mt19937_64 rng(haveSeed ? seed : autoSeed());
    unsigned long long gsize = 0;
    vector<pos_t> offs;
    for (auto& c : g.names) { offs.push_back((pos_t)gsize); gsize += g.sizes[c]; }
    vector<Rec> exclRecs, inclRecs;
    BinIndex exclIdx;
    if (haveExcl) { loadOld(excl, exclRecs); }
    if (haveIncl) { loadOld(incl, inclRecs); }
    vector<Rec> placed;   // for noOverlapping, appended to exclusion
    exclIdx.recs = &exclRecs;
    for (int i = 0; i < (int)exclRecs.size(); i++) exclIdx.add(i);
    OldReader rd; rd.open(fn);
    Rec r;
    string& ob = OUT.buf;
    vector<int> cand;
    auto overlapsExcl = [&](const string& chrom, pos_t s, pos_t e) -> bool {
        if (!haveExcl && !noOverlap) return false;
        exclIdx.query(chrom, s, e, cand);
        pos_t len = e - s;
        for (int k : cand) {
            const Rec& x = exclRecs[k];
            pos_t ov = std::min(e, x.end) - std::max(s, x.start);
            if (ov > 0 && (double)ov / (double)len >= frac) return true;
        }
        return false;
    };
    while (rd.next(r)) {
        pos_t len = r.end - r.start;
        bool ok = false;
        string chrom; pos_t start = 0;
        long tries = 0;
        while (true) {
            if (haveIncl) {
                if (inclRecs.empty()) break;
                const Rec& in = inclRecs[rng() % inclRecs.size()];
                chrom = in.chrom();
                pos_t il = in.end - in.start;
                start = in.start + (pos_t)(rng() % (unsigned long long)(il > 0 ? il : 1));
            } else if (sameChrom) {
                chrom = r.chrom();
                pos_t cs = g.size(chrom);
                if (cs <= 0) break;
                start = (pos_t)(rng() % (unsigned long long)cs);
            } else if (chromFirst) {
                size_t k = rng() % g.names.size();
                chrom = g.names[k];
                start = (pos_t)(rng() % (unsigned long long)g.sizes[chrom]);
            } else {
                unsigned long long p = rng() % gsize;
                size_t k = std::upper_bound(offs.begin(), offs.end(), (pos_t)p) - offs.begin() - 1;
                chrom = g.names[k];
                start = (pos_t)p - offs[k];
            }
            pos_t cs = g.size(chrom);
            pos_t end = start + len;
            bool fits = end <= cs;
            if (!fits && beyond) { end = cs; fits = true; }
            if (fits && !overlapsExcl(chrom, start, end)) {
                ok = true;
                r.start = start; r.end = end;
                break;
            }
            tries++;
            if (tries >= maxTries) break;
        }
        if (!ok) {
            errmsg("Error, line " + itos(rd.lineNo) + ": tried " + itos(maxTries) + " potential loci for entry, but could not avoid excluded regions.  Ignoring entry and moving on.\n");
            continue;
        }
        r.f[0] = chrom;
        bool wasZl = r.zl;
        r.zl = false;
        if (wasZl) { r.zl = true; }
        appendOld(ob, r); outnl();
        if (noOverlap) {
            Rec x; x.f = {chrom}; x.start = r.start; x.end = r.end;
            exclRecs.push_back(x);
            exclIdx.add((int)exclRecs.size() - 1);
        }
    }
    OUT.flush();
    return 0;
}

int main_sample(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn, strandOpt;
    bool haveI = false, haveSeed = false, header = false, haveS = false;
    long n = 1000000;
    unsigned long long seed = 0;
    if (a.empty()) helpAndExit("sample", "***** ERROR: No input file given. Exiting. *****\n");
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("sample");
        if (s == "-i") { if (i + 1 >= a.size()) helpAndExit("sample", "***** ERROR: -i option given, but no input file specified. *****\n"); fn = a[++i]; haveI = true; }
        else if (s == "-n") { if (i + 1 < a.size()) n = atol(a[++i].c_str()); }
        else if (s == "-seed") { if (i + 1 < a.size()) { seed = strtoull(a[++i].c_str(), nullptr, 10); haveSeed = true; } }
        else if (s == "-s") { if (i + 1 < a.size()) { strandOpt = a[++i]; haveS = true; } }
        else if (s == "-header") header = true;
        else if (s == "-ubam" || s == "-bed" || s == "-nobuf") {}
        else if (s == "-iobuf") { if (i + 1 < a.size()) i++; }
        else helpAndExit("sample", "***** ERROR: Unrecognized parameter: " + s + " *****\n");
    }
    if (!haveI) helpAndExit("sample", "***** ERROR: No input file given. Exiting. *****\n");
    char want = 0;
    if (haveS) {
        if (strandOpt == "forward") want = '+';
        else if (strandOpt == "reverse") want = '-';
        else helpAndExit("sample", "***** ERROR: -s option must be followed by forward or reverse. *****\n");
    }
    OUT.setNewApi();
    RecReader rd; rd.open(fn);
    std::mt19937_64 rng(haveSeed ? seed : autoSeed());
    vector<Rec> res;
    Rec r;
    unsigned long long cnt = 0;
    while (rd.next(r)) {
        if (want && r.strand != want) continue;
        cnt++;
        if ((long)res.size() < n) { res.push_back(r); continue; }
        unsigned long long j = rng() % cnt;
        if (j < (unsigned long long)n) res[j] = r;
    }
    if (header) for (auto& h : rd.header) { outs(h); outnl(); }
    for (auto& x : res) { appendRec(OUT.buf, x); outnl(); }
    OUT.flush();
    return 0;
}
