#include "oldbed.h"
#include "tools.h"
#include <climits>
#include <unistd.h>

int main_summary(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn, gfile;
    bool haveI = false, haveG = false;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("summary");
        if (s == "-i") { if (i + 1 >= a.size()) helpAndExit("summary", "***** ERROR: -i option given, but no input file specified. *****\n"); fn = a[++i]; haveI = true; }
        else if (s == "-g") { if (i + 1 >= a.size()) helpAndExit("summary", "***** ERROR: -g option given, but no genome file specified. *****\n"); gfile = a[++i]; haveG = true; }
        else helpAndExit("summary", "***** ERROR: Unrecognized parameter: " + s + " *****\n");
    }
    if (!haveG) helpAndExit("summary", "***** ERROR: no -g genome file provided. *****\n");
    if (!haveI) helpAndExit("summary", "***** ERROR: No input file given. Exiting. *****\n");
    OUT.setNewApi();
    {
        InFile t;
        if (!t.open(gfile)) die("Error: Can't open genome file " + gfile + ". Exiting...\n");
    }
    Genome g; g.load(gfile);
    RecReader rd; rd.open(fn);
    std::unordered_map<string, long> cnt;
    std::unordered_map<string, pos_t> bp, mn, mx;
    Rec r;
    while (rd.next(r)) {
        if (!g.has(r.chrom())) die("Error: requested chromosome " + r.chrom() + " does not exist in the genome file " + gfile + ". Exiting.\n");
        pos_t l = r.end - r.start;
        const string& c = r.chrom();
        if (!cnt.count(c)) { cnt[c] = 0; bp[c] = 0; mn[c] = l; mx[c] = l; }
        cnt[c]++; bp[c] += l;
        if (l < mn[c]) mn[c] = l;
        if (l > mx[c]) mx[c] = l;
    }
    long totN = 0; pos_t totBp = 0, gsize = 0, gmin = LLONG_MAX, gmax = 0;
    for (auto& c : g.names) {
        gsize += g.sizes[c];
        if (cnt.count(c)) { totN += cnt[c]; totBp += bp[c]; gmin = std::min(gmin, mn[c]); gmax = std::max(gmax, mx[c]); }
    }
    string& ob = OUT.buf;
    ob += "chrom\tchrom_length\tnum_ivls\ttotal_ivl_bp\tchrom_frac_genome\tfrac_all_ivls\tfrac_all_bp\tmin\tmax\tmean\n";
    for (auto& c : g.names) {
        pos_t cs = g.sizes[c];
        long n = cnt.count(c) ? cnt[c] : 0;
        pos_t b = n ? bp[c] : 0;
        ob += c + "\t" + itos(cs) + "\t" + itos(n) + "\t" + itos(b) + "\t" + fmtFixed((double)cs / gsize, 9) + "\t";
        ob += fmtFixed(totN ? (double)n / totN : 0.0, 9) + "\t" + fmtFixed(totBp ? (double)b / totBp : 0.0, 9) + "\t";
        if (n) ob += itos(mn[c]) + "\t" + itos(mx[c]) + "\t" + fmtFixed((double)b / n, 9) + "\t";
        else ob += "-1\t-1\t-1";
        outnl();
    }
    ob += "all\t" + itos(gsize) + "\t" + itos(totN) + "\t" + itos(totBp) + "\t1.0\t1.0\t1.0\t" + itos(gmin) + "\t" + itos(gmax) + "\t";
    if (totN) ob += fmtFixed((double)totBp / totN, 9); else ob += "-nan";
    outnl();
    OUT.flush();
    return 0;
}

int main_split(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn = "-", prefix = "_split", algo = "size";
    long n = 0;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") { printHelp("split", stdout); return 0; }
        if (s == "-v" || s == "--version") { printf("bedtools split v%s\n", BT_VERSION); return 0; }
        if (s == "-i" || s == "--input") { if (i + 1 < a.size()) fn = a[++i]; }
        else if (s == "-n" || s == "--number") { if (i + 1 < a.size()) n = atol(a[++i].c_str()); }
        else if (s == "-p" || s == "--prefix") { if (i + 1 < a.size()) prefix = a[++i]; }
        else if (s == "-a" || s == "--algorithm") { if (i + 1 < a.size()) algo = a[++i]; }
        else { errmsg("Unknown option " + s + "\n"); exit(1); }
    }
    if (n <= 0) { errmsg("Error: num_chunks==0.\n\n"); printHelp("split", stderr); exit(1); }
    if (algo != "size" && algo != "simple") { errmsg("Unknown split algorithm " + algo + "\n"); exit(1); }
    vector<Rec> recs;
    OldReader rd; rd.open(fn);
    Rec r;
    while (rd.next(r)) recs.push_back(r);
    vector<vector<size_t>> files(n);
    vector<pos_t> sizes(n, 0);
    if (algo == "simple") {
        for (size_t i = 0; i < recs.size(); i++) { files[i % n].push_back(i); sizes[i % n] += recs[i].end - recs[i].start; }
    } else {
        vector<size_t> ord(recs.size());
        for (size_t i = 0; i < ord.size(); i++) ord[i] = i;
        std::stable_sort(ord.begin(), ord.end(), [&](size_t x, size_t y) { return (recs[x].end - recs[x].start) > (recs[y].end - recs[y].start); });
        for (size_t i : ord) {
            long best = 0;
            for (long k = 1; k < n; k++) if (sizes[k] < sizes[best]) best = k;
            files[best].push_back(i);
            sizes[best] += recs[i].end - recs[i].start;
        }
    }
    string& ob = OUT.buf;
    for (long k = 0; k < n; k++) {
        char nm[64]; snprintf(nm, sizeof nm, ".%05ld.bed", k + 1);
        string fname = prefix + nm;
        FILE* f = fopen(fname.c_str(), "w");
        if (!f) die("Error: cannot open " + fname + " for writing\n");
        string buf;
        for (size_t i : files[k]) { appendOld(buf, recs[i]); buf += '\n'; }
        fwrite(buf.data(), 1, buf.size(), f);
        fclose(f);
        ob += fname + "\t" + itos(sizes[k]) + "\t" + itos(files[k].size()); outnl();
    }
    OUT.flush();
    return 0;
}
