// pairtobed, pairtopair
#include "oldbed.h"
#include "overlap.h"
#include "tools.h"

namespace {
struct PE {
    vector<string> f;
    string c1, c2;
    pos_t s1, e1, s2, e2;
    char st1 = '.', st2 = '.';
    string name;
};
}

static bool readBedpe(const string& fn, vector<PE>& out) {
    InFile in;
    if (!in.open(fn)) die("Error: The requested bedpe file (" + fn + ") could not be opened. Exiting!\n");
    string line;
    long ln = 0;
    while (in.getline(line)) {
        ln++;
        if (line.empty() || isHeaderLine(line)) continue;
        PE p;
        splitTab(line, p.f);
        if (p.f.size() < 6) die("Error: malformed BEDPE entry at line " + itos(ln) + ". Exiting.\n");
        p.c1 = p.f[0]; p.s1 = atoll(p.f[1].c_str()); p.e1 = atoll(p.f[2].c_str());
        p.c2 = p.f[3]; p.s2 = atoll(p.f[4].c_str()); p.e2 = atoll(p.f[5].c_str());
        if (p.f.size() > 6) p.name = p.f[6];
        if (p.f.size() > 8) p.st1 = p.f[8] == "+" ? '+' : p.f[8] == "-" ? '-' : '.';
        if (p.f.size() > 9) p.st2 = p.f[9] == "+" ? '+' : p.f[9] == "-" ? '-' : '.';
        out.push_back(std::move(p));
    }
    return true;
}

static void appendPE(string& o, const PE& p) {
    for (size_t i = 0; i < p.f.size(); i++) { if (i) o += '\t'; o += p.f[i]; }
}

int main_pairtobed(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fa, fb, type = "either";
    bool haveA = false, haveB = false, s = false, S = false;
    double f = 1e-9;
    for (size_t i = 0; i < a.size(); i++) {
        const string& x = a[i];
        if (x == "-h" || x == "--help") helpAndExit("pairtobed");
        if (x == "-a" || x == "-abam") { if (i + 1 < a.size()) { fa = a[++i]; haveA = true; } }
        else if (x == "-b") { if (i + 1 < a.size()) { fb = a[++i]; haveB = true; } }
        else if (x == "-type") { if (i + 1 < a.size()) type = a[++i]; }
        else if (x == "-f") { if (i + 1 < a.size()) f = atof(a[++i].c_str()); }
        else if (x == "-s") s = true;
        else if (x == "-S") S = true;
        else if (x == "-ubam" || x == "-bedpe" || x == "-ed") {}
        else errHelpExit("pairtobed", "\n*****ERROR: Unrecognized parameter: " + x + " *****\n\n");
    }
    auto err = [&](const string& m) { errHelpExit("pairtobed", "\n*****\n*****ERROR: " + m + "\n*****\n"); };
    if (!haveA || !haveB) err("Need -a and -b files. ");
    static const char* types[] = {"either", "neither", "both", "xor", "notboth", "ispan", "ospan", "notispan", "notospan", nullptr};
    bool ok = false; for (int k = 0; types[k]; k++) if (type == types[k]) ok = true;
    if (!ok) err("Invalid -type. Please use either, neither, both, xor, notboth, ispan, ospan, notispan, or notospan.");
    if (s && S) err("Please choose either -s or -S, not both.");
    vector<PE> A; readBedpe(fa, A);
    vector<Rec> B; loadOld(fb, B);
    BinIndex idx; idx.build(B);
    string& ob = OUT.buf;
    vector<int> cand;
    auto hitsFor = [&](const string& c, pos_t st, pos_t en, char strand, vector<int>& out, bool useStrand) {
        out.clear();
        idx.query(c, st, en, cand);
        pos_t len = en - st;
        for (int k : cand) {
            const Rec& br = B[k];
            if (useStrand && s && !(strand != '.' && br.strand != '.' && strand == br.strand)) continue;
            if (useStrand && S && !(strand != '.' && br.strand != '.' && strand != br.strand)) continue;
            pos_t ov = std::min(en, br.end) - std::max(st, br.start);
            if (ov <= 0) continue;
            if (len > 0 && (double)ov / (double)len < f) continue;
            out.push_back(k);
        }
    };
    vector<int> h1, h2;
    for (auto& p : A) {
        if (type == "ispan" || type == "ospan" || type == "notispan" || type == "notospan") {
            if (p.c1 != p.c2) continue;
            pos_t st, en;
            if (type == "ispan" || type == "notispan") { st = p.e1; en = p.s2; }
            else { st = p.s1; en = p.e2; }
            hitsFor(p.c1, st, en, '.', h1, false);
            if (type == "ispan" || type == "ospan") {
                for (int k : h1) { appendPE(ob, p); ob += '\t'; appendOld(ob, B[k]); outnl(); }
            } else if (h1.empty()) { appendPE(ob, p); outnl(); }
            continue;
        }
        hitsFor(p.c1, p.s1, p.e1, p.st1, h1, true);
        hitsFor(p.c2, p.s2, p.e2, p.st2, h2, true);
        bool o1 = !h1.empty(), o2 = !h2.empty();
        auto report = [&]() {
            for (int k : h1) { appendPE(ob, p); ob += '\t'; appendOld(ob, B[k]); outnl(); }
            for (int k : h2) { appendPE(ob, p); ob += '\t'; appendOld(ob, B[k]); outnl(); }
        };
        if (type == "either") { if (o1 || o2) report(); }
        else if (type == "neither") { if (!o1 && !o2) { appendPE(ob, p); outnl(); } }
        else if (type == "both") { if (o1 && o2) report(); }
        else if (type == "xor") { if (o1 != o2) report(); }
        else if (type == "notboth") {
            if (o1 != o2) report();
            else if (!o1 && !o2) { appendPE(ob, p); outnl(); }
        }
    }
    OUT.flush();
    return 0;
}

