}

void bamWriteHeader(BgzfWriter& w, const BamHeader& h) {
    string s = "BAM\1";
    put32(s, (uint32_t)h.text.size());
    s += h.text;
    put32(s, (uint32_t)h.names.size());
    for (size_t i = 0; i < h.names.size(); i++) {
        put32(s, (uint32_t)h.names[i].size() + 1);
        s += h.names[i]; s += '\0';
        put32(s, (uint32_t)h.lens[i]);
    }
    w.write(s.data(), s.size());
    w.flush();
}

void bamWriteRaw(BgzfWriter& w, const string& raw) {
    w.flushTry(4 + raw.size());
    string s; put32(s, (uint32_t)raw.size()); s += raw;
    w.write(s.data(), s.size());
}

int bamReg2bin(pos_t beg, pos_t end) {
    --end;
    if (beg >> 14 == end >> 14) return (int)(((1 << 15) - 1) / 7 + (beg >> 14));
    if (beg >> 17 == end >> 17) return (int)(((1 << 12) - 1) / 7 + (beg >> 17));
    if (beg >> 20 == end >> 20) return (int)(((1 << 9) - 1) / 7 + (beg >> 20));
    if (beg >> 23 == end >> 23) return (int)(((1 << 6) - 1) / 7 + (beg >> 23));
    if (beg >> 26 == end >> 26) return (int)(((1 << 3) - 1) / 7 + (beg >> 26));
    return 0;
}

void bamBlocks(const BamRec& b, vector<std::pair<pos_t, pos_t>>& blocks, bool splitN, bool splitD) {
    blocks.clear();
    pos_t cur = b.pos, bs = b.pos;
    for (uint32_t c : b.cigar) {
        int op = c & 0xf; pos_t l = c >> 4;
        if (op == 0 || op == 7 || op == 8) cur += l;
        else if (op == 2) {
            if (splitD) { if (cur > bs) blocks.push_back({bs, cur}); cur += l; bs = cur; }
            else cur += l;
        } else if (op == 3) {
            if (splitN) { if (cur > bs) blocks.push_back({bs, cur}); cur += l; bs = cur; }
            else cur += l;
        }
    }
    if (cur > bs || blocks.empty()) blocks.push_back({bs, cur});
}

bool bamGetTagNum(const BamRec& b, const char* tag, double& v, bool& isInt) {
    const string& t = b.tags;
    size_t o = 0;
    while (o + 3 <= t.size()) {
        char t0 = t[o], t1 = t[o + 1], ty = t[o + 2];
        o += 3;
        bool match = t0 == tag[0] && t1 == tag[1];
        auto rd = [&](size_t n) { int64_t x = 0; memcpy(&x, t.data() + o, n); o += n; return x; };
        switch (ty) {
            case 'A': if (match) { v = (unsigned char)t[o]; isInt = true; return true; } o += 1; break;
            case 'c': { int8_t x = (int8_t)t[o]; o += 1; if (match) { v = x; isInt = true; return true; } break; }
            case 'C': { uint8_t x = (uint8_t)t[o]; o += 1; if (match) { v = x; isInt = true; return true; } break; }
            case 's': { int16_t x; memcpy(&x, t.data() + o, 2); o += 2; if (match) { v = x; isInt = true; return true; } break; }
            case 'S': { uint16_t x; memcpy(&x, t.data() + o, 2); o += 2; if (match) { v = x; isInt = true; return true; } break; }
            case 'i': { int32_t x; memcpy(&x, t.data() + o, 4); o += 4; if (match) { v = x; isInt = true; return true; } break; }
            case 'I': { uint32_t x; memcpy(&x, t.data() + o, 4); o += 4; if (match) { v = x; isInt = true; return true; } break; }
            case 'f': { float x; memcpy(&x, t.data() + o, 4); o += 4; if (match) { v = x; isInt = false; return true; } break; }
            case 'Z': case 'H': { size_t e = t.find('\0', o); if (e == string::npos) return false; o = e + 1; if (match) return false; break; }
            case 'B': {
                char sub = t[o]; o += 1; int32_t n; memcpy(&n, t.data() + o, 4); o += 4;
                int sz = (sub == 'c' || sub == 'C') ? 1 : (sub == 's' || sub == 'S') ? 2 : 4;
                o += (size_t)n * sz;
                if (match) return false;
                break;
            }
            default: return false;
        }
        (void)rd;
    }
    return false;
}

// ------------------------------------------------------------- RecReader glue
struct BamCtx { BamReader rd; };

bool bamDetect(InFile& in) {
    // peek decompressed bytes: InFile buffer is filled lazily; use gzread then gzrewind not possible on stdin.
    // We read 4 bytes and push them into InFile's pending buffer via gzungetc.
    unsigned char m[4];
    int k = gzread(in.gz, m, 4);
    if (k <= 0) return false;
    for (int i = k - 1; i >= 0; i--) gzungetc(m[i], in.gz);
    return k == 4 && m[0] == 'B' && m[1] == 'A' && m[2] == 'M' && m[3] == 1;
}

void bamOpenReader(RecReader& rd, InFile& in) {
    BamCtx* c = new BamCtx();
    if (!c->rd.open(in)) die("Error: could not parse BAM header of " + rd.fn + "\n");
    rd.bamCtx = c;
    rd.bamHeaderText = c->rd.hdr.text;
    rd.bamRefNames = c->rd.hdr.names;
    for (auto l : c->rd.hdr.lens) rd.bamRefLens.push_back(l);
    rd.ft = FT_BAM; rd.bk = BK_BED12; rd.nf = 12;
}

bool bamNextRec(RecReader& rd, Rec& r) {
    BamCtx* c = (BamCtx*)rd.bamCtx;
    BamRec* b = new BamRec();
    while (true) {
        if (!c->rd.next(*b)) { delete b; return false; }
        if (b->flag & 0x4) continue;
        if (b->refID < 0) continue;
        break;
    }
    string chrom = c->rd.hdr.names[b->refID];
    pos_t s = b->pos, e = b->end();
    string name = b->name;
    if (b->flag & 0x1) { if (b->flag & 0x40) name += "/1"; else if (b->flag & 0x80) name += "/2"; }
    vector<std::pair<pos_t, pos_t>> bl;
    bamBlocks(*b, bl, true, false);
    string sizes, starts;
    for (auto& x : bl) { sizes += itos(x.second - x.first) + ","; starts += itos(x.first - s) + ","; }
    r.f = {chrom, itos(s), itos(e), name, itos(b->mapq), (b->flag & 0x10) ? "-" : "+", itos(s), itos(e), "0,0,0", itos(bl.size()), sizes, starts};
    r.start = r.ostart = s; r.end = r.oend = e;
    r.zl = false;
    if (r.start == r.end) { r.zl = true; r.start -= 1; r.end += 1; }
    r.strand = (b->flag & 0x10) ? '-' : '+';
    r.hasStrand = true;
    r.ft = FT_BAM; r.bk = BK_BED12;
    r.idx = rd.recNo++;
    if (r.bam) delete (BamRec*)r.bam;
    r.bam = b;
    return true;
}

void bamGetBlocks(const Rec& r, vector<std::pair<pos_t, pos_t>>& blocks, bool splitD) {
    bamBlocks(*(BamRec*)r.bam, blocks, true, splitD);
}
