// bamtobed, bedtobam, bamtofastq
#include "bam.h"
#include "oldbed.h"
#include "tools.h"
#include <unistd.h>

static bool openBam(const string& fn, InFile& in, BamReader& br) {
    if (!in.open(fn)) {
        errmsg("[E::hts_open_format_impl] Failed to open file " + fn + "\n");
        return false;
    }
    if (!bamDetect(in)) {
        errmsg("[E::sam_parse1] missing SAM header\n[W::sam_read1] Parse error at line 1\n");
        return false;
    }
    return br.open(in);
}

int main_bamtobed(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn = "stdin", color = "255,0,0", tag;
    bool bedpe = false, mate1 = false, bed12 = false, split = false, splitD = false, ed = false, cigar = false, haveTag = false;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("bamtobed");
        if (s == "-i") { if (i + 1 < a.size()) fn = a[++i]; }
        else if (s == "-bedpe") bedpe = true;
        else if (s == "-mate1") mate1 = true;
        else if (s == "-bed12") bed12 = true;
        else if (s == "-split") split = true;
        else if (s == "-splitD") { splitD = true; split = true; }
        else if (s == "-ed") ed = true;
        else if (s == "-tag") { if (i + 1 < a.size()) { tag = a[++i]; haveTag = true; } }
        else if (s == "-color") { if (i + 1 < a.size()) color = a[++i]; }
        else if (s == "-cigar") cigar = true;
        else errHelpExit("bamtobed", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    (void)bedpe; (void)mate1;
    if (ed) { tag = "NM"; haveTag = true; }
    InFile in; BamReader br;
    if (!openBam(fn, in, br)) die("Failed to open BAM file " + fn + "\n");
    BamRec b;
    string& ob = OUT.buf;
    vector<std::pair<pos_t, pos_t>> blocks;
    while (br.next(b)) {
        if (b.flag & 0x4) continue;
        if (b.refID < 0) continue;
        const string& chrom = br.hdr.names[b.refID];
        string name = b.name;
        if (b.flag & 0x1) { if (b.flag & 0x40) name += "/1"; else if (b.flag & 0x80) name += "/2"; }
        char strand = (b.flag & 0x10) ? '-' : '+';
        pos_t s = b.pos, e = b.end();
        auto scoreStr = [&]() -> string {
            if (!haveTag) return itos(b.mapq);
            double v; bool isInt;
            if (!bamGetTagNum(b, tag.c_str(), v, isInt)) {
                OUT.flush();
                errmsg("The requested tag (" + tag + ") was not found in the BAM file.  Exiting\n");
                exit(1);
            }
            return isInt ? itos((pos_t)v) : fmtDefault(v);
        };
        if (bed12) {
            bamBlocks(b, blocks, true, splitD);
            ob += chrom + "\t" + itos(s) + "\t" + itos(e) + "\t" + name + "\t";
            OUT.flush();
            ob += scoreStr();
            ob += string("\t") + strand + "\t" + itos(s) + "\t" + itos(e) + "\t" + color + "\t" + itos(blocks.size()) + "\t";
            for (size_t k = 0; k < blocks.size(); k++) { if (k) ob += ','; ob += itos(blocks[k].second - blocks[k].first); }
            ob += '\t';
            for (size_t k = 0; k < blocks.size(); k++) { if (k) ob += ','; ob += itos(blocks[k].first - s); }
            if (cigar) { ob += '\t'; ob += b.cigarStr(); }
            outnl();
        } else if (split) {
            bamBlocks(b, blocks, true, splitD);
            for (auto& bl : blocks) {
                ob += chrom + "\t" + itos(bl.first) + "\t" + itos(bl.second) + "\t" + name + "\t";
                OUT.flush();
                ob += scoreStr();
                ob += string("\t") + strand;
                if (cigar) { ob += '\t'; ob += b.cigarStr(); }
                outnl();
            }
        } else {
            ob += chrom + "\t" + itos(s) + "\t" + itos(e) + "\t" + name + "\t";
            if (haveTag) OUT.flush();
            ob += scoreStr();
            ob += string("\t") + strand;
            if (cigar) { ob += '\t'; ob += b.cigarStr(); }
            outnl();
        }
    }
    OUT.flush();
    return 0;
}

static void put32s(string& s, uint32_t v) { for (int i = 0; i < 4; i++) s += (char)((v >> (8 * i)) & 0xff); }
static void put16s(string& s, uint16_t v) { s += (char)(v & 0xff); s += (char)(v >> 8); }

int main_bedtobam(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn, gfile;
    bool haveI = false, haveG = false, bed12 = false;
    int mapq = 255;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("bedtobam");
        if (s == "-i") { if (i + 1 < a.size()) { fn = a[++i]; haveI = true; } }
        else if (s == "-g") { if (i + 1 < a.size()) { gfile = a[++i]; haveG = true; } }
        else if (s == "-mapq") { if (i + 1 < a.size()) mapq = atoi(a[++i].c_str()); }
        else if (s == "-bed12") bed12 = true;
        else if (s == "-ubam") {}
        else errHelpExit("bedtobam", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    if (!haveI && !isatty(0)) { fn = "stdin"; haveI = true; }
    if (!haveI) errHelpExit("bedtobam", "\n*****\n*****ERROR: Need -i (BED) file. \n*****\n");
    if (!haveG) errHelpExit("bedtobam", "\n*****\n*****ERROR: Need -g (genome) file. \n*****\n");
    Genome g; g.load(gfile);
    OldReader rd; rd.open(fn);
    BamHeader h;
    h.text = "@HD\tVN:1.0\tSO:unsorted\n@PG\tID:BEDTools_bedToBam\tVN:V" + string(BT_VERSION) + "\n";
    for (auto& c : g.names) {
        h.text += "@SQ\tSN:" + c + "\tAS:" + gfile + "\tLN:" + itos(g.sizes[c]) + "\n";
        h.names.push_back(c); h.lens.push_back((int32_t)g.sizes[c]);
    }
    BgzfWriter w;
    bamWriteHeader(w, h);
    Rec r;
    vector<std::pair<pos_t, pos_t>> blocks;
    while (rd.next(r)) {
        string name;
        if (r.ft == FT_GFF) name = r.f[2];
        else if (r.f.size() > 3) name = r.f[3];
        else { w.close(); die("Error: BED entry without name found at line: " + itos(rd.lineNo) + ".  Exiting!\n"); }
        pos_t s = r.zl ? r.start + 1 : r.start, e = r.zl ? r.end - 1 : r.end;
        vector<uint32_t> cig;
        if (bed12 && r.ft == FT_BED && r.f.size() >= 12) {
            getBlocks(r, blocks);
            pos_t cur = s;
            for (size_t k = 0; k < blocks.size(); k++) {
                if (k > 0 && blocks[k].first > cur) cig.push_back((uint32_t)((blocks[k].first - cur) << 4 | 3));
                cig.push_back((uint32_t)((blocks[k].second - blocks[k].first) << 4 | 0));
                cur = blocks[k].second;
            }
        } else cig.push_back((uint32_t)((e - s) << 4 | 0));
        int ref = g.idx(r.chrom());
        string rec;
        put32s(rec, (uint32_t)ref);
        put32s(rec, (uint32_t)s);
        rec += (char)(name.size() + 1);
        rec += (char)(mapq & 0xff);
        put16s(rec, (uint16_t)bamReg2bin(s, e));
        put16s(rec, (uint16_t)cig.size());
        put16s(rec, (uint16_t)(r.strand == '-' ? 16 : 0));
        put32s(rec, 0);
        put32s(rec, (uint32_t)-1);
        put32s(rec, (uint32_t)-1);
        put32s(rec, 0);
        rec += name; rec += '\0';
        for (uint32_t c : cig) put32s(rec, c);
        bamWriteRaw(w, rec);
    }
    w.close();
    return 0;
}

int main_bamtofastq(int argc, char** argv) {
