    string fn, fq, fq2;
    bool haveI = false, haveFq = false, haveFq2 = false, tags = false;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-h" || s == "--help") helpAndExit("bamtofastq");
        if (s == "-i") { if (i + 1 < a.size()) { fn = a[++i]; haveI = true; } }
        else if (s == "-fq") { if (i + 1 < a.size()) { fq = a[++i]; haveFq = true; } }
        else if (s == "-fq2") { if (i + 1 < a.size()) { fq2 = a[++i]; haveFq2 = true; } }
        else if (s == "-tags") tags = true;
        else errHelpExit("bamtofastq", "\n*****ERROR: Unrecognized parameter: " + s + " *****\n\n");
    }
    (void)tags;
    if (!haveI || !haveFq) errHelpExit("bamtofastq", "\n*****\n*****ERROR: Need -i (BAM) file and -fq (FASTQ) file. \n*****\n");
    InFile in; BamReader br;
    if (!openBam(fn, in, br)) die("Failed to open BAM file " + fn + "\n");
    FILE* f1 = fopen(fq.c_str(), "w");
    FILE* f2 = haveFq2 ? (fq2 == fq ? f1 : fopen(fq2.c_str(), "w")) : nullptr;
    BamRec b;
    auto rc = [](string s) {
        std::reverse(s.begin(), s.end());
        for (auto& c : s) {
            switch (c) { case 'A': c = 'T'; break; case 'T': c = 'A'; break; case 'C': c = 'G'; break; case 'G': c = 'C'; break;
                         case 'a': c = 't'; break; case 't': c = 'a'; break; case 'c': c = 'g'; break; case 'g': c = 'c'; break; default: break; }
        }
        return s;
    };
    while (br.next(b)) {
        if (b.flag & 0x900) continue;
        string seq = b.seq, q;
        for (char c : b.qual) q += (char)(c + 33);
        if (b.flag & 0x10) { seq = rc(seq); std::reverse(q.begin(), q.end()); }
        string name = b.name;
        FILE* f = f1;
        if (haveFq2 && (b.flag & 0x1)) { if (b.flag & 0x80) f = f2; name += (b.flag & 0x40) ? "/1" : "/2"; }
        string out = "@" + name + "\n" + seq + "\n+\n" + q + "\n";
        fwrite(out.data(), 1, out.size(), f);
    }
    fclose(f1);
    if (f2 && f2 != f1) fclose(f2);
    return 0;
}
