// multicov, tag
#include "bam.h"
#include "oldbed.h"
#include "overlap.h"
#include "tools.h"

static bool loadBamAll(const string& fn, BamHeader& h, vector<BamRec>& v) {
    InFile in; BamReader br;
    if (!in.open(fn) || !bamDetect(in) || !br.open(in)) return false;
    h = br.hdr;
    BamRec b;
    while (br.next(b)) v.push_back(b);
    return true;
}

int main_multicov(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    vector<string> bams;
    string bed;
    bool haveBed = false, split = false, s = false, S = false, recip = false, dup = false, qcfail = false, proper = false;
    double f = 1e-9; int q = 0;
    for (size_t i = 0; i < a.size(); i++) {
        const string& x = a[i];
        if (x == "-h" || x == "--help") helpAndExit("multicov");
        if (x == "-bams") { while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-')) bams.push_back(a[++i]); }
        else if (x == "-bed") { if (i + 1 < a.size()) { bed = a[++i]; haveBed = true; } }
        else if (x == "-split") split = true;
        else if (x == "-s") s = true;
        else if (x == "-S") S = true;
        else if (x == "-f") { if (i + 1 < a.size()) f = atof(a[++i].c_str()); }
        else if (x == "-r") recip = true;
        else if (x == "-q") { if (i + 1 < a.size()) q = atoi(a[++i].c_str()); }
        else if (x == "-D") dup = true;
        else if (x == "-F") qcfail = true;
        else if (x == "-p") proper = true;
        else errHelpExit("multicov", "\n*****ERROR: Unrecognized parameter: " + x + " *****\n\n");
    }
    if (bams.empty() || !haveBed) errHelpExit("multicov", "\n*****\n*****ERROR: Need -bams and -bed files. \n*****\n");
    for (auto& b : bams) {
        string base = b.size() > 4 && endsWith(b, ".bam") ? b.substr(0, b.size() - 4) : b;
        if (!fileExists(b + ".bai") && !fileExists(base + ".bai") && !fileExists(b + ".csi")) die("Could not find/load indexes.\n\n");
    }
    vector<vector<Rec>> reads(bams.size());
    vector<BinIndex> idx(bams.size());
    for (size_t k = 0; k < bams.size(); k++) {
        BamHeader h; vector<BamRec> v;
        if (!loadBamAll(bams[k], h, v)) die("Could not find/load indexes.\n\n");
        for (auto& b : v) {
            if (b.flag & 0x4 || b.refID < 0) continue;
            if (b.mapq < q) continue;
            if (!dup && (b.flag & 0x400)) continue;
            if (!qcfail && (b.flag & 0x200)) continue;
            if (proper && !(b.flag & 0x2)) continue;
            Rec r; r.f = {h.names[b.refID]}; r.start = b.pos; r.end = b.end();
            if (r.end <= r.start) r.end = r.start + 1;
            r.strand = (b.flag & 0x10) ? '-' : '+';
            r.bam = std::make_shared<BamRec>(b);
            r.ft = FT_BAM;
            reads[k].push_back(r);
        }
        idx[k].build(reads[k]);
    }
    OldReader rd; rd.open(bed);
    Rec r;
    vector<int> cand;
    vector<std::pair<pos_t, pos_t>> blocks;
    string& ob = OUT.buf;
    while (rd.next(r)) {
        appendOld(ob, r);
        for (size_t k = 0; k < bams.size(); k++) {
            idx[k].query(r.chrom(), r.start, r.end, cand);
            long cnt = 0;
            for (int c : cand) {
                const Rec& x = reads[k][c];
                if (s && x.strand != r.strand) continue;
                if (S && x.strand == r.strand) continue;
                pos_t ov = 0;
                if (split) { bamBlocks(*x.bam, blocks, true, true); for (auto& bl : blocks) { pos_t o = ovlLen(bl.first, bl.second, r.start, r.end); if (o > 0) ov += o; } }
                else ov = ovlLen(x.start, x.end, r.start, r.end);
                if (ov <= 0) continue;
                if ((double)ov / (r.end - r.start) < f) continue;
                if (recip && (double)ov / (x.end - x.start) < f) continue;
                cnt++;
            }
            ob += '\t'; ob += itos(cnt);
        }
        outnl();
    }
    OUT.flush();
    return 0;
}

int main_tag(int argc, char** argv) {
    vector<string> a(argv + 2, argv + argc);
    string fn, tag = "YB";
    vector<string> files, labels;
    bool haveI = false, s = false, S = false, useNames = false, useScores = false, useIntervals = false;
    double f = 1e-9;
    for (size_t i = 0; i < a.size(); i++) {
        const string& x = a[i];
        if (x == "-h" || x == "--help") helpAndExit("tag");
        if (x == "-i") { if (i + 1 < a.size()) { fn = a[++i]; haveI = true; } }
        else if (x == "-files") { while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-')) files.push_back(a[++i]); }
        else if (x == "-labels") { while (i + 1 < a.size() && (a[i + 1].empty() || a[i + 1][0] != '-')) labels.push_back(a[++i]); }
        else if (x == "-s") s = true;
        else if (x == "-S") S = true;
        else if (x == "-f") { if (i + 1 < a.size()) f = atof(a[++i].c_str()); }
        else if (x == "-tag") { if (i + 1 < a.size()) tag = a[++i]; }
        else if (x == "-names") useNames = true;
        else if (x == "-scores") useScores = true;
        else if (x == "-intervals") useIntervals = true;
        else errHelpExit("tag", "\n*****ERROR: Unrecognized parameter: " + x + " *****\n\n");
    }
    if (!haveI || files.empty()) errHelpExit("tag", "\n*****\n*****ERROR: Need -i (BAM) file and -files. \n*****\n");
    vector<vector<Rec>> B(files.size());
    vector<BinIndex> idx(files.size());
    for (size_t k = 0; k < files.size(); k++) { loadOld(files[k], B[k]); idx[k].build(B[k]); }
    InFile in; BamReader br;
    if (!in.open(fn) || !bamDetect(in) || !br.open(in)) die("Failed to open BAM file " + fn + "\n");
    BgzfWriter w;
    bamWriteHeader(w, br.hdr);
    BamRec b;
    vector<int> cand;
    while (br.next(b)) {
        string val;
        if (!(b.flag & 0x4) && b.refID >= 0) {
            const string& chrom = br.hdr.names[b.refID];
            pos_t st = b.pos, en = b.end();
            char strand = (b.flag & 0x10) ? '-' : '+';
            vector<string> parts;
            for (size_t k = 0; k < files.size(); k++) {
                idx[k].query(chrom, st, en > st ? en : st + 1, cand);
                vector<string> hv;
                for (int c : cand) {
                    const Rec& x = B[k][c];
                    if (s && x.strand != strand) continue;
                    if (S && x.strand == strand) continue;
                    pos_t ov = ovlLen(x.start, x.end, st, en);
                    if (ov <= 0) continue;
                    if (en > st && (double)ov / (en - st) < f) continue;
                    string nm = x.f.size() > 3 ? x.f[3] : "", sc = x.f.size() > 4 ? x.f[4] : "", sd = x.f.size() > 5 ? x.f[5] : "";
                    if (useNames) hv.push_back(nm);
                    else if (useScores) hv.push_back(sc);
                    else if (useIntervals) hv.push_back((k < labels.size() ? labels[k] : "") + ":" + x.chrom() + ":" + itos(x.start) + "-" + itos(x.end) + "," + nm + "," + sc + "," + sd);
                    else { hv.push_back(k < labels.size() ? labels[k] : ""); break; }
                }
                if (!hv.empty()) parts.push_back(join(hv, ","));
            }
            val = join(parts, useIntervals ? "," : ";");
        }
        string raw = b.raw;
        if (!val.empty()) { raw += tag.substr(0, 2); raw += 'Z'; raw += val; raw += '\0'; }
        bamWriteRaw(w, raw);
    }
    w.close();
    return 0;
}
