int main_bedpetobam(int argc, char** argv) {
    oldPreScan("bedpetobam", argc, argv, false);
    vector<string> a(argv + 2, argv + argc);
    string fn, gfile;
    bool haveI = false, haveG = false;
    int mapq = 255;
    for (size_t i = 0; i < a.size(); i++) {
        const string& s = a[i];
        if (s == "-i") { if (i + 1 < a.size()) { fn = a[++i]; haveI = true; } }
        else if (s == "-g") { if (i + 1 < a.size()) { gfile = a[++i]; haveG = true; } }
        else if (s == "-mapq") { if (i + 1 < a.size()) mapq = atoi(a[++i].c_str()); }
        else if (s == "-ubam") {}
        else oldUnknown(s);
    }
    if (!haveI && !isatty(0)) { fn = "stdin"; haveI = true; }
    if (!haveI) oldNeed("Need -i (BEDPE) file. ");
    if (!haveG) oldNeed("Need -g (genome) file. ");
    oldFinish("bedpetobam");
    Genome g; g.load(gfile);
    BamHeader h;
    h.text = "@HD\tVN:1.0\tSO:unsorted\n@PG\tID:BEDTools_bedpeToBam\tVN:V" + string(BT_VERSION) + "\n";
    for (auto& c : g.names) {
        h.text += "@SQ\tSN:" + c + "\tAS:" + gfile + "\tLN:" + itos(g.sizes[c]) + "\n";
        h.names.push_back(c); h.lens.push_back((int32_t)g.sizes[c]);
    }
    BgzfWriter w;
    bamWriteHeader(w, h);
    InFile in;
    if (!in.open(fn)) die("Error: The requested file (" + fn + ") could not be opened. Error message: (No such file or directory). Exiting!\n");
    string line; vector<string> f;
    auto p32 = [](string& s, uint32_t v) { for (int i = 0; i < 4; i++) s += (char)((v >> (8 * i)) & 0xff); };
    auto p16 = [](string& s, uint16_t v) { s += (char)(v & 0xff); s += (char)(v >> 8); };
    while (in.getline(line)) {
        if (line.empty() || isHeaderLine(line)) continue;
        splitTab(line, f);
        if (f.size() < 10) continue;
        string name = f[6];
        pos_t s1 = atoll(f[1].c_str()), e1 = atoll(f[2].c_str()), s2 = atoll(f[4].c_str()), e2 = atoll(f[5].c_str());
        int r1 = std::max(0, g.idx(f[0])), r2 = std::max(0, g.idx(f[3]));
        bool m1 = f[8] == "-", m2 = f[9] == "-";
        for (int k = 0; k < 2; k++) {
            int ref = k ? r2 : r1, mref = k ? r1 : r2;
            pos_t s = k ? s2 : s1, e = k ? e2 : e1, ms = k ? s1 : s2;
            uint16_t flag = 1 | 2 | (k ? 0x80 : 0x40);
            if (k ? m2 : m1) flag |= 0x10;
            if (k ? m1 : m2) flag |= 0x20;
            string rec;
            p32(rec, (uint32_t)ref); p32(rec, (uint32_t)s);
            rec += (char)(name.size() + 1); rec += (char)(mapq & 0xff);
            p16(rec, (uint16_t)bamReg2bin(s, e)); p16(rec, 1); p16(rec, flag);
            p32(rec, 0); p32(rec, (uint32_t)mref); p32(rec, (uint32_t)ms);
            pos_t tl = (r1 == r2) ? (k ? -(e2 - s1) : (e2 - s1)) : 0;
            p32(rec, (uint32_t)tl);
            rec += name; rec += '\0';
            p32(rec, (uint32_t)((e - s) << 4));
            bamWriteRaw(w, rec);
        }
    }
    w.close();
    return 0;
}
