struct SortState { bool have = false; string prev; pos_t ps = -1; std::set<string> seen; };
}
static void sweepCheckOne(const Rec& r, SortState& st, const string& fn) {
    bool bad = false;
    if (st.have) {
        if (r.chrom() != st.prev) { if (st.seen.count(r.chrom())) bad = true; }
        else if (r.start < st.ps) bad = true;
    }
    if (bad) {
        string l; appendRecCoords(l, r, r.start, r.end);
        die("Error: Sorted input specified, but the file " + fn + " has the following out of order record\n" + l + "\n");
    }
    if (!st.have || r.chrom() != st.prev) st.seen.insert(r.chrom());
    st.prev = r.chrom(); st.ps = r.start; st.have = true;
}

// Simulates the interleaved reading order of a chromsweep over A and B and reports
// the first out-of-order record encountered.
void sweepSortCheck(const vector<Rec>& A, const string& fa, const vector<Rec>& B, const string& fb) {
    SortState sa, sb;
    size_t j = 0, checked = 0;
    for (size_t i = 0; i < A.size(); i++) {
        sweepCheckOne(A[i], sa, fa);
        while (j < B.size()) {
            if (checked <= j) { sweepCheckOne(B[j], sb, fb); checked = j + 1; }
            const Rec& b = B[j];
            bool consume;
            if (b.chrom() == A[i].chrom()) consume = b.start < A[i].end;
            else consume = b.chrom() < A[i].chrom();
            if (!consume) break;
            j++;
        }
    }
}
